const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
async function api(path, options={}){const requestPath=path==='/api/state'?`${path}?_=${Date.now()}`:path;const res=await fetch(requestPath,{cache:'no-store',...options,headers:{'content-type':'application/json',...(options.headers||{})}});let data;try{data=await res.json()}catch{data={}}if(!res.ok){const failure=new Error(data.error||`Request failed (${res.status})`);failure.errors=data.errors;throw failure}return data}
function toast(message,error=false){const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.textContent=message;$('#toast-region').append(node);setTimeout(()=>node.remove(),3200)}
function iconButton(name,label,attrs=''){return `<button class="icon-button" title="${esc(label)}" aria-label="${esc(label)}" ${attrs}>${svg(name)}</button>`}
function relativeDate(date){if(!date)return 'Just now';let delta=Math.max(0,Date.now()-new Date(date).getTime());if(delta<60_000)return 'Just now';if(delta<3_600_000)return `${Math.floor(delta/60_000)}m ago`;if(delta<86_400_000)return `${Math.floor(delta/3_600_000)}h ago`;return `${Math.floor(delta/86_400_000)}d ago`}
function initials(name){return (name||'You').trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join('')||'YO'}
function render(){
  state.refreshPending=false;state.cardRefreshPending=false;state.processingRefreshPending=false;state.streamRefreshPending=false;
  const activePage=state.page==='processing'?'applications':state.page;
  const navPage=['pipeline','applications'].includes(activePage)?'applications':activePage;
  document.querySelectorAll('.workspace-nav .nav-item[data-page]').forEach(item=>{const selected=item.dataset.page===navPage;item.setAttribute('aria-current',selected?'page':'false');item.classList.toggle('active',selected)});
  $('#page-context').textContent=pageNames[state.page]||'Overview';
  $('#nav-jobs-count').textContent=String(state.jobs.length).padStart(2,'0');
  $('#nav-app-count').textContent=String(applicationJobs().length).padStart(2,'0');
  const waitingQuestions=questionsCount(state);const questionBadge=$('#nav-questions-count');if(questionBadge){questionBadge.textContent=String(waitingQuestions).padStart(2,'0');questionBadge.hidden=!waitingQuestions;questionBadge.setAttribute('aria-label',`${waitingQuestions} question${waitingQuestions===1?'':'s'} waiting`);}
  const identity=profileIdentity(state);
  $('#account-name').textContent=identity.name||'Your workspace'; $('#avatar').textContent=initials(identity.name);$('#top-account-name').textContent=identity.name||'Profile';$('#top-avatar').textContent=initials(identity.name);
  $('#account-status').textContent=identity.name ? identity.needsReview?'Review needed':'Profile confirmed' : 'Set up your profile';
  const worker=state.worker||{mode:'embedded',status:'ready'};
  const queued=state.tasks.some(t=>t.status==='queued'),running=state.tasks.some(t=>t.status==='running');
  const workerText=worker.mode==='container'?(worker.status==='ready'?(running?'Application in progress':queued?'Application queued':'Docker worker ready'):'Docker worker offline'):(running?'Application in progress':queued?'Preparing in background':'Local worker ready');
  $('#worker-label').textContent=workerText;
  $('#worker-indicator').classList.toggle('offline',worker.status!=='ready');
  $('#service-state').textContent=worker.mode==='container'?(worker.status==='ready'?'Docker · browser ready':'Docker · start worker'):'Local mode';
  $('#agent-status').textContent=workerText;
  const needsAttention=state.tasks.filter(task=>task.status==='needs_you'||task.status==='needs_setup').length;
  $('#nav-app-count').setAttribute('aria-label',`${applicationJobs().length} application items${needsAttention?`, ${needsAttention} need attention`:''}`);
  const wrap=$('#page-wrap'); wrap.innerHTML=({home:renderHome,setup:renderSetup,jobs:renderJobs,autoApply:renderAutoApply,pipeline:renderPipeline,applications:renderApplications,processing:renderProcessing,profile:renderProfile,answers:renderAnswers,questions:renderQuestions,inbox:renderInbox,settings:renderSettings}[state.page]||renderHome)();
  renderAssistantMessages();
  document.querySelectorAll('#page-wrap [data-icon]').forEach(el=>el.innerHTML=svg(el.dataset.icon));
  bindPageActions();bindStream(document);
  bindResumeEditor();
  bindMailbox();
  bindProcessingDocuments();
  updateQuestionsBar?.();
}
function renderQuestions(){return heading('QUESTIONS','Questions only you can answer.','Answer a factual question once and Daymark fills it for every matching application. Consents and legal questions stay your call.')+renderQuestionsInbox(state)}
function heading(eyebrow,title,desc,button=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
function renderAssistantMessages(){const region=$('#assistant-messages');if(!region)return;const messages=state.assistantMessages.length?state.assistantMessages:[{role:'assistant',text:'I can help you find roles, check application progress, or open your inbox. Actions that start work will ask first.'}];region.innerHTML=messages.slice(-16).map(item=>`<p class="assistant-bubble ${item.role==='user'?'user':''}">${esc(item.text)}</p>`).join('');region.scrollTop=region.scrollHeight;}
function assistantSay(role,text){state.assistantMessages.push({role,text});renderAssistantMessages();}
async function sendAssistantMessage(text){const message=String(text||'').trim();if(!message)return;assistantSay('user',message);const command=resolveAssistantCommand(message);
 if(command==='collect'){assistantSay('assistant','Collecting can make paid requests to Apify. Daymark will add at most 100 new roles today. Continue?');if(confirm('Start job collection now? Apify may charge for the collection run. Daymark imports no more than 100 new roles today.')){await collect();assistantSay('assistant','Collection was sent to the local job worker. I’ll show its progress in the Dashboard and Discover pages.')}else assistantSay('assistant','Collection cancelled.');return;}
 if(command==='import-job'){navigate('jobs');$('#import-role-url')?.focus();assistantSay('assistant','Paste the public job link in the Add a job link card. Daymark will fetch the posting before adding it.');return;}
 if(command==='resume-task'){const resumable=state.tasks.filter(task=>['paused','failed'].includes(task.status)&&!task.finalReviewReady&&!task.submitAttemptedAt).sort((a,b)=>Date.parse(b.updatedAt||b.createdAt||'')-Date.parse(a.updatedAt||a.createdAt||''))[0];if(!resumable){const checkpoint=state.tasks.find(task=>task.status==='needs_you'||task.finalReviewReady);if(checkpoint){state.processingJobId=checkpoint.jobId;navigate('processing');assistantSay('assistant','This application is waiting at a user checkpoint or final review. I opened it so you can inspect the saved step; I did not resume or submit it.');}else assistantSay('assistant','There is no paused or failed application task ready to resume.');return;}if(confirm(`Resume ${resumable.company} · ${resumable.role}? The background worker will continue from its saved checkpoint.`)){state.processingJobId=resumable.jobId;navigate('processing');await taskAction(resumable.id,'resume');assistantSay('assistant','The task is back in the local queue. Its live progress is on the processing page.');}else assistantSay('assistant','Resume cancelled.');return;}
 const destinations={discover:'jobs',applications:'pipeline',inbox:'inbox','auto-apply':'autoApply',profile:'profile'};if(destinations[command]){navigate(destinations[command]);assistantSay('assistant',({discover:'Here are your roles, sorted by overall match and freshness.',applications:'I opened your application pipeline. Choose a card to see its live processing details.',inbox:'I opened your application inbox. Messages are read locally through Proton Bridge.','auto-apply':'Your matching, daily cap, and skip rules are here. Changes are saved locally.',profile:'Your profile and editable master resume are open.'})[command]);return;}
 if(/\b(apply|application)\b/i.test(message)){navigate('jobs');assistantSay('assistant','Choose a role card and press Apply. Daymark will prepare a source-only resume locally. Your first test is configured to stop at final review.');return;}
 assistantSay('assistant','I can navigate your local workspace, collect fresh roles after confirmation, import a job link, or resume a paused task after confirmation. Try one of the suggested requests.');}
function taskCard(task){const ready=task.status==='ready_for_review'&&task.hasArtifacts;const approved=task.review?.approvalStatus==='approved';return `<article class="task-card"><div class="task-state-icon">${svg(task.status==='queued'?'clock':approved?'check':'file')}</div><div class="task-main"><strong>${esc(task.company)} · ${esc(task.role)}</strong><p>${esc(displayTaskMessage(task.message))}</p>${task.compensation?`<p>Compensation: ${esc(task.compensation.answer)} · ${esc(task.compensation.source)}</p>`:''}<div class="task-progress"><span style="width:${task.progress||5}%"></span></div>${ready?`<div class="button-row task-downloads"><button class="${approved?'secondary-button':'primary-button'}" data-review-task="${esc(task.id)}">${approved?'Review or edit resume':'Review tailored resume'}</button>${approved?`<a class="secondary-button" href="/api/tasks/${esc(task.id)}/files/resume.pdf">Resume PDF</a><a class="secondary-button" href="/api/tasks/${esc(task.id)}/files/resume.docx">Resume DOCX</a><a class="secondary-button" href="/api/tasks/${esc(task.id)}/files/cover-letter.docx">Cover letter</a><button class="secondary-button" data-job-answer="${esc(task.id)}">Draft an application answer</button><button class="primary-button" data-fill-task="${esc(task.id)}">Fill application form</button>`:`<span class="review-needed">Review required before download or form filling</span>`}</div>${task.review?.changes?.length?`<details class="change-log"><summary>${task.review.changes.length} tailoring changes</summary>${task.review.changes.map(change=>`<div class="change-entry"><strong>${esc(change.section||'Resume')}</strong><span class="source-status ${change.sourceStatus==='needs_confirmation'?'needs-confirmation':''}">${change.sourceStatus==='needs_confirmation'?'Needs your confirmation':change.sourceStatus==='user_confirmed'?'Confirmed by you':change.sourceStatus==='user_reviewed'?'Edited by you':'Source excerpt checked'}</span><p>${esc(change.reason||'Aligned content to this role.')}</p>${change.before?`<p><span>Before</span> ${esc(change.before)}</p>`:''}<p><span>After</span> ${esc(change.after)}</p>${change.sourceExcerpt?`<p><span>Source</span> ${esc(change.sourceExcerpt)}</p>`:''}</div>`).join('')}</details>`:''}${approved&&task.review?.versions?.length?`<details class="change-log"><summary>Approved resume versions (${task.review.versions.length})</summary>${task.review.versions.map(version=>`<div class="change-entry"><strong>Version ${version.version}</strong><span>${esc(relativeDate(version.approvedAt))}</span><p><a href="/api/tasks/${esc(task.id)}/versions/${version.version}/resume.pdf">PDF</a> · <a href="/api/tasks/${esc(task.id)}/versions/${version.version}/resume.docx">DOCX</a></p></div>`).join('')}</details>`:''}${task.formSnapshot?`<details><summary>${esc(task.formSnapshot.adapter)} form · ${task.formSnapshot.fields.length} fields filled</summary><p>Review remaining questions, then submit manually.</p><div class="dialog-tags">${task.formSnapshot.controls.map(c=>`<span class="skill-tag">${esc(c.label||c.name||c.placeholder||c.type||c.tag)}${c.required?' · required':''}</span>`).join('')}</div><a class="secondary-button" href="${esc(task.formSnapshot.url)}" target="_blank" rel="noreferrer">Open application page</a></details>`:''}`:''}</div><div class="task-actions"><span class="state-pill ${esc(task.status)}">${esc(task.status.replaceAll('_',' '))}</span>${ready?`<span class="state-pill ${approved?'approved':'review'}">${approved?'resume approved':'resume review'}</span>`:''}${task.status==='queued'?`<button class="text-button" data-task-action="pause" data-id="${task.id}">Pause</button>`:task.status==='paused'||task.status==='needs_you'||task.status==='failed'?`<button class="text-button" data-task-action="resume" data-id="${task.id}">${task.status==='failed'?'Retry':'Resume'}</button>`:`<button class="text-button" data-task-action="cancel" data-id="${task.id}">Remove</button>`}</div></article>`}
const fieldLabels={name:'Full name',phone:'Phone',linkedin:'LinkedIn',headline:'Professional summary',skills:'Skills',workHistory:'Work history',education:'Education',projects:'Projects',certifications:'Certifications',resumeEmail:'Email found in resume',location:'Home location',github:'GitHub',website:'Website / portfolio'};
