function applicationDetailsCard(p){const f=(key,label,hint='',type='text')=>`<div class="field"><label for="ad-${key}">${label}</label><input id="ad-${key}" name="${key}" type="${type}" value="${esc(p[key])}" placeholder="${esc(hint)}"/></div>`;return `<section class="content-card"><h2>Application details</h2><p>Used to fill employer forms automatically. Empty name fields are derived from your full name, and city/state from your home location.</p><form id="application-details-form" class="form-grid">${f('firstName','Legal first name',(p.name||'').split(/\s+/)[0])}${f('middleName','Middle name')}${f('lastName','Legal last name',(p.name||'').split(/\s+/).slice(-1)[0])}${f('preferredName','Preferred name')}${f('addressLine1','Address line 1')}${f('addressLine2','Address line 2')}${f('city','City')}${f('state','State / province')}${f('postalCode','Postal code')}${f('country','Country','United States')}${f('yearsExperience','Years of experience','','number')}${f('noticePeriod','Notice period','2 weeks')}${f('desiredSalary','Desired salary','Leave blank to use the company range or your fallback')}${f('referral','How you usually hear about roles','LinkedIn')}<div class="field full"><button class="secondary-button" type="submit">Save application details</button> <span id="application-details-status" role="status"></span></div></form></section>`;}
function renderProfile(){
 const p=state.profile||{},draft=state.resumeDraft,d=draft?.fields||{},merged={...p,...d};
 state.editorDocument=draft ? (draft.document?cleanResumeDocument(draft.document):null) : (p.resumeDocument?cleanResumeDocument(p.resumeDocument):null);
 const sectionKeys=['workHistory','education','projects','certifications'];
 return heading('YOUR STORY','Your resume. Ready to edit.','Map your resume with NVIDIA, review each section, and confirm your master resume.')+`
 <section class="content-card"><h2>Upload & mapping</h2><p>Selectable-text PDF or DOCX, up to 12 MB. Scanned resumes require pasted text.</p><label for="resume-file">Upload resume</label><input id="resume-file" type="file" accept=".pdf,.docx"/><p id="resume-status" role="status">${esc(p.resumeName||'No resume uploaded yet.')}</p><div class="button-row">${p.resumeText?'<button class="secondary-button" data-action="reparse">Map again with NVIDIA</button>':''}<button class="text-button" data-action="paste-resume">Paste resume text</button></div><p>NVIDIA receives resume text only after your confirmation. Missing sections stay empty.</p>${draft?.method==='local'?'<div class="inline-note"><strong>Previous local extraction</strong><p>This draft was created by the old parser. Choose “Map again with NVIDIA” to extract the complete summary and separate employment entries.</p></div>':''}<div id="profile-error" role="alert"></div></section>
 ${applicationDetailsCard(p)}<div class="profile-layout"><section class="content-card"><h2>Master resume editor</h2><p>Edits save as a draft. Confirmation activates your profile.</p><form id="profile-form" class="form-grid">${profileFields.filter(key=>!state.editorDocument||!sectionKeys.includes(key)).map(key=>`<div class="field ${['name','phone'].includes(key)?'':'full'}"><label for="profile-${key}">${esc(fieldLabels[key]||key)}${key==='name'?' (required)':''}</label>${['headline','skills',...sectionKeys].includes(key)?`<textarea id="profile-${key}" name="${key}" rows="${key==='workHistory'?8:4}">${esc(merged[key])}</textarea>`:`<input id="profile-${key}" name="${key}" value="${esc(merged[key])}" ${key==='name'?'required':''}/>`}</div>`).join('')}${state.editorDocument?`<div id="structured-resume-editor" class="field full">${renderResumeEntries()}</div>${sectionKeys.map(key=>`<input type="hidden" id="profile-${key}" name="${key}" value="${esc(merged[key])}"/>`).join('')}`:''}<div class="field full"><label>Application email</label><p>${esc(p.email||'Add your application email in Settings.')}</p><small>Used separately from the email in your uploaded resume.</small></div><div class="field full"><label for="profile-roleSearch">Roles to search for (required)</label><input id="profile-roleSearch" name="roleSearch" required value="${esc(d.roleSearch??(p.roleSearch||draft?.roleSuggestions?.join(', ')||''))}"/></div><div class="field full"><label for="profile-locationSearch">Locations to search</label><input id="profile-locationSearch" name="locationSearch" value="${esc(d.locationSearch??p.locationSearch)}"/></div><div class="field full"><p id="resume-draft-status" role="status">${draft?'Draft ready for review.':'Your confirmed master remains saved.'}</p><button class="primary-button" type="submit">Confirm master resume & continue ${svg('arrow')}</button></div></form></section>
 <aside><section class="content-card"><h2>Live resume preview</h2><iframe id="master-resume-preview" class="resume-preview-frame" title="Live master resume preview" sandbox src="/api/profile/template${draft?'?draft=1':''}"></iframe>${draft?.warnings?.length?`<details open><summary>Extraction checks</summary><ul>${draft.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}<p>Only sections containing information appear in the template. Application tailoring uses a separate copy.</p></section></aside></div>`;
}
function renderResumeEntries(){
 return Object.entries(entrySections).map(([section,spec])=>{
  const legacyKey=section==='experience'?'workHistory':section;
  if(state.editorDocument.legacy[legacyKey])return `<fieldset class="resume-entry-section"><legend>${esc(spec.label)}</legend><p>Section text retained. Remap to separate entries.</p><label for="legacy-${legacyKey}">${esc(spec.label)} text</label><textarea id="legacy-${legacyKey}" data-resume-legacy="${legacyKey}" rows="7">${esc(state.editorDocument.legacy[legacyKey])}</textarea></fieldset>`;
  return `<fieldset class="resume-entry-section"><legend>${esc(spec.label)} <span>(${state.editorDocument[section].length})</span></legend>${state.editorDocument[section].map((entry,index)=>`<article class="resume-entry"><div class="section-title-row"><h3>${esc(entry.employer||entry.institution||entry.name||`${spec.label} ${index+1}`)}</h3><button type="button" class="text-button" data-remove-entry="${section}" data-entry-index="${index}" aria-label="Remove ${esc(spec.label)} ${index+1}">Remove</button></div><div class="form-grid">${Object.entries(spec.fields).map(([key,label])=>`<div class="field"><label for="entry-${section}-${index}-${key}">${esc(label)}</label><input id="entry-${section}-${index}-${key}" data-resume-section="${section}" data-entry-index="${index}" data-entry-field="${key}" value="${esc(entry[key])}"/></div>`).join('')}${spec.bullets?`<div class="field full"><label for="entry-${section}-${index}-bullets">Accomplishments · one bullet per line</label><textarea rows="6" id="entry-${section}-${index}-bullets" data-resume-section="${section}" data-entry-index="${index}" data-entry-field="bullets">${esc(entry.bullets.join('\n'))}</textarea></div>`:''}</div></article>`).join('')}<button type="button" class="secondary-button" data-add-entry="${section}">Add ${section==='experience'?'experience':section==='education'?'education':section==='projects'?'project':'certification'}</button></fieldset>`;
 }).join('');
}
function profileEditorBody(form){
 const fields=Object.fromEntries(new FormData(form));
 if(state.editorDocument)Object.assign(fields,documentProfileFields(state.editorDocument));
 return {fields,...(state.editorDocument?{document:state.editorDocument}:{})};
}
function updateResumeEditor(form){
 const body=profileEditorBody(form);
 for(const [key,value] of Object.entries(body.fields))if(form.elements[key]?.type==='hidden')form.elements[key].value=value;
 const preview=$('#master-resume-preview');if(preview)preview.srcdoc=resumePreviewDocument(masterResume({...state.profile,...body.fields}));
 $('#account-name').textContent=body.fields.name||'Your workspace';$('#avatar').textContent=initials(body.fields.name);$('#account-status').textContent='Review needed';
 state.resumeDraft={...(state.resumeDraft||{}),fields:body.fields,document:body.document,editedByUser:true};
 state.onboarding.profileConfirmed=false;state.onboarding.completed=false;
 clearTimeout(resumeDraftTimer);const status=$('#resume-draft-status');if(status)status.textContent='Saving draft…';
 resumeDraftTimer=setTimeout(()=>{resumeDraftSave=resumeDraftSave.catch(()=>{}).then(()=>api('/api/profile/draft',{method:'POST',body:JSON.stringify(body)}));resumeDraftSave.then(()=>{if(status?.isConnected)status.textContent='Draft saved locally.'}).catch(error=>{if(status?.isConnected)status.textContent=`Draft not saved: ${error.message}`});},700);
}
function bindResumeEditor(){
 const form=$('#profile-form');if(!form)return;
 form.oninput=event=>{
  const input=event.target;
  if(input.dataset.resumeSection){const entry=state.editorDocument[input.dataset.resumeSection][Number(input.dataset.entryIndex)];const key=input.dataset.entryField;entry[key]=key==='bullets'?input.value.split('\n').filter(x=>x.trim()):input.value;}
  if(input.dataset.resumeLegacy)state.editorDocument.legacy[input.dataset.resumeLegacy]=input.value;
  updateResumeEditor(form);
 };
 form.querySelectorAll('[data-add-entry]').forEach(button=>button.onclick=()=>{const section=button.dataset.addEntry,spec=entrySections[section];state.editorDocument[section].push({...Object.fromEntries(Object.keys(spec.fields).map(key=>[key,''])),...(spec.bullets?{bullets:[]}: {})});$('#structured-resume-editor').innerHTML=renderResumeEntries();bindResumeEditor();updateResumeEditor(form);form.querySelector(`[data-resume-section="${section}"][data-entry-index="${state.editorDocument[section].length-1}"]`)?.focus();});
 form.querySelectorAll('[data-remove-entry]').forEach(button=>button.onclick=()=>{if(!confirm('Remove this entry from your draft master resume?'))return;state.editorDocument[button.dataset.removeEntry].splice(Number(button.dataset.entryIndex),1);$('#structured-resume-editor').innerHTML=renderResumeEntries();bindResumeEditor();updateResumeEditor(form);});
}
function eeoSection(values){return `<fieldset class="answer-choice eeo-section"><legend>Employer EEO questions (optional)</legend><p>Saved once and used only when an application asks. Daymark never guesses these. Leave a question on “Answer per application” and the agent will stop and ask you.</p>${eeoQuestionCatalog.map(q=>`<div class="eeo-question"><strong>${esc(q.label)}</strong><div class="choice-options">${q.options.map((option,i)=>`<label class="choice-label"><input type="radio" name="${q.id}" value="${esc(option)}" ${values[q.id]===option?'checked':''}/> ${esc(option)}</label>`).join('')}<label class="choice-label"><input type="radio" name="${q.id}" value="" ${!values[q.id]?'checked':''}/> Answer per application</label></div></div>`).join('')}</fieldset>`;}
function answerLibrary(){const entries=Object.entries(state.applicationAnswerPack||{});return `<section class="content-card answer-library"><h2>Learned answers</h2><p>Only answers you explicitly save are remembered and reused, including when another site words the question differently. Edit or remove any of them.</p>${entries.length?entries.map(([label,item])=>`<form class="library-entry" data-library-label="${esc(label)}"><label><strong>${esc(label.replace(/\*+$/,''))}</strong>${item.type==='textarea'?`<textarea name="answer" rows="3">${esc(item.answer)}</textarea>`:`<input name="answer" value="${esc(Array.isArray(item.answer)?item.answer.join(', '):item.answer)}"/>`}</label><div class="button-row"><button class="secondary-button" type="submit">Save</button><button class="text-button" type="button" data-library-delete>Delete</button></div></form>`).join(''):'<p class="muted-line">Nothing learned yet. Choose Remember for future applications when answering a question to save it here.</p>'}</section>`;}
function renderAnswers(){const values=state.answerPack?.values||{};return heading('YOUR DEFAULTS','Less repeating. More control.','Save factual choices once. You can change them anytime or answer individual questions per application.')+`
 <section class="content-card"><form id="answer-pack-form">${questionCatalog.map(q=>`<fieldset class="answer-choice"><legend>${esc(q.label)}</legend><p id="help-${q.id}">${esc(q.help)}</p><div class="choice-options">${q.options.map((option,i)=>`<label class="choice-label" for="${q.id}-${i}"><input id="${q.id}-${i}" type="${q.multiple?'checkbox':'radio'}" name="${q.id}" value="${esc(option)}" aria-describedby="help-${q.id}" ${(q.multiple?values[q.id]?.includes(option):values[q.id]===option)?'checked':''}/> ${esc(option)}</label>`).join('')}${!q.multiple?`<label class="choice-label"><input type="radio" name="${q.id}" value="" ${!values[q.id]?'checked':''}/> Answer per application</label>`:''}</div>${q.id==='availability'?`<label for="start-date">Start date (if Specific date)</label><input type="date" id="start-date" name="startDate" value="${esc(values.startDate)}"/>`:''}</fieldset>`).join('')}${eeoSection(values)}<div class="inline-note"><strong>Compensation</strong><p>Use the company’s published base-pay range. If none is available, use $110,000 USD annually. This value is shown for review with each application.</p></div><p>Accomplishments, experience descriptions, and motivation are drafted on demand from the job description and the tailored resume for that application. Hobbies require facts you provide.</p><div id="answer-pack-error" role="alert"></div><div class="button-row"><button class="secondary-button" type="submit" name="finish" value="later">Save & finish later</button><button class="primary-button" type="submit" name="finish" value="complete">Save answer pack & continue</button></div></form></section>${answerLibrary()}${state.answers?.length?`<details class="content-card"><summary>Previous answers retained for review</summary><p>These are preserved locally and excluded from automatic reuse.</p>${state.answers.map(a=>`<p><strong>${esc(a.question)}</strong><br/>${esc(a.answer)}</p>`).join('')}</details>`:''}`;}
function trackerTabs(active){return `<nav class="tracker-tabs" aria-label="Tracker views"><button data-page="inbox" ${active==='inbox'?'aria-current="page"':''}>Inbox</button><button data-page="pipeline" ${active==='pipeline'?'aria-current="page"':''}>Pipeline</button><button data-page="applications" ${active==='applications'?'aria-current="page"':''}>Applications</button></nav>`;}
function renderInbox(){return heading('TRACKER / INBOX','Every next step, in one inbox.','Application messages stay on this Mac and connect to the roles they reference.')+renderMailbox();}
function integrationTile(icon,title,desc,configured,savedLabel='Saved locally'){return `<div class="setup-tile"><div class="setup-symbol">${svg(icon)}</div><div class="setup-detail"><strong>${title}</strong><p>${desc}</p><span class="setup-state ${configured?'ready':''}">${configured?savedLabel:'Needs setup'}</span></div></div>`}

function automationCard(){const p=state.preferences||{},a=p.autoApply||{},r=p.skipRules||{},d=p.defaults||{};return `<section class="content-card"><h2>Auto-apply & skip rules</h2><p>After each collection the agent queues your best new matches and records roles it skipped with the reason. Every application pauses at final review before you choose to submit.</p><form id="automation-form" class="form-grid"><div class="field full"><label class="inline-check"><input type="checkbox" name="enabled" ${a.enabled!==false?'checked':''}/> Auto-apply to new matches</label></div><div class="field"><label for="auto-min">Minimum match %</label><input id="auto-min" name="minMatch" type="number" min="0" max="100" value="${esc(a.minMatch??70)}"/></div><div class="field"><label for="auto-cap">Applications per day</label><input id="auto-cap" name="dailyCap" type="number" min="0" max="50" value="${esc(a.dailyCap??10)}"/></div><div class="field full"><label class="inline-check"><input type="checkbox" name="clearance" ${r.clearance!==false?'checked':''}/> Skip roles that require a security clearance</label><label class="inline-check"><input type="checkbox" name="remoteOnly" ${r.remoteOnly?'checked':''}/> Remote roles only</label></div><div class="field"><label for="rule-salary">Skip if published pay tops out below ($/yr)</label><input id="rule-salary" name="minSalary" type="number" min="0" step="1000" value="${esc(r.minSalary||'')}" placeholder="No minimum"/></div><div class="field"><label for="rule-companies">Excluded companies (comma separated)</label><input id="rule-companies" name="excludedCompanies" value="${esc((r.excludedCompanies||[]).join(', '))}"/></div><div class="field"><label for="rule-titles">Excluded title words</label><input id="rule-titles" name="excludedTitles" value="${esc((r.excludedTitles||[]).join(', '))}" placeholder="intern, manager"/></div><div class="field"><label for="def-resume">Default resume</label><select id="def-resume" name="resumeMode"><option value="tailored" ${d.resumeMode!=='default'?'selected':''}>Tailored per role</option><option value="default" ${d.resumeMode==='default'?'selected':''}>My master resume</option></select></div><div class="field"><label for="def-cover">Cover letter</label><select id="def-cover" name="coverLetter"><option value="on" ${d.coverLetter!=='off'?'selected':''}>On</option><option value="off" ${d.coverLetter==='off'?'selected':''}>Off</option></select></div><div class="field full"><button class="secondary-button" type="submit">Save rules</button> <span id="automation-status" role="status"></span></div></form></section>`;}
function renderSettings(){const worker=state.worker||{mode:'embedded',status:'ready'},forwarding=state.mailForwarding||{recipient:'',enabled:false};return `${heading('YOUR SETUP','Everything in its right place.','Connect the services that help your local workspace do its work.')}
${worker.mode==='container'?`<section class="content-card worker-settings"><div class="section-title-row"><h2>Application worker</h2><span class="worker-health ${worker.status==='ready'?'ready':''}"><i></i>${worker.status==='ready'?'Browser ready':'Offline'}</span></div><p>${worker.status==='ready'?'The isolated Chromium worker is online. Applications run in the background and stop at checkpoints that need you.':'The dashboard is running, but the Docker worker is not available. Start Docker Desktop, then run the worker command below.'}</p><div class="worker-steps"><div><b>1</b><span><strong>Prepare once</strong><code>npm run worker:setup</code></span></div><div><b>2</b><span><strong>Start or stop</strong><code>npm run worker:up</code><code>npm run worker:down</code></span></div></div>${worker.status==='ready'&&worker.viewerUrl?`<a class="secondary-button" href="${esc(worker.viewerUrl)}" target="_blank" rel="noreferrer">Open live browser viewer ${svg('arrow')}</a>`:''}</section>`:''}
${automationCard()}<section class="content-card"><h2>Application agent</h2><label class="ls-toggle"><input type="checkbox" role="switch" data-pref-review checked disabled/><span class="ls-track" aria-hidden="true"></span><span class="ls-toggle-copy"><b>Final review required</b><small>Daymark pauses here for every application. Submission is always a separate action.</small></span></label><label class="ls-toggle"><input type="checkbox" role="switch" data-pref-ai ${state.preferences?.aiAnswers?'checked':''}/><span class="ls-track" aria-hidden="true"></span><span class="ls-toggle-copy"><b>AI-drafted answers</b><small>For open-ended questions, send the question, your tailored resume and the job description to NVIDIA to draft a grounded answer. Never used for legal, demographic or consent questions. AI answers are marked on the review receipt.</small></span></label></section>
<section class="content-card"><h2>Connections</h2><div class="connection-checks">${['apify','nvidia','proton'].map(service=>`<div><strong>${({apify:'Apify',nvidia:'NVIDIA',proton:'Proton Bridge'})[service]}</strong><span id="check-${service}" role="status">${state.connectionChecks?.[service]?.status==='connected'?'Connected at last check':state.integrations[service]?'Saved · check connection':'Needs setup'}</span><button class="secondary-button" type="button" data-check-service="${service}">Check connection</button></div>`).join('')}</div><p>Keys stay in this app’s private local settings file and aren’t displayed again after saving.</p><div class="setup-grid">${integrationTile('compass','Apify job feed','Collect up to 100 new roles per day from the career-site feed.',state.integrations.apify,'Token saved')}${integrationTile('spark','NVIDIA model','Generate application materials after a per-job confirmation.',state.integrations.nvidia,'Key saved')}${integrationTile('mail','Application email','Email address used on your applications.',state.integrations.email,'Address saved')}${integrationTile('lock','Proton Bridge','Read verification and password-reset messages from local IMAP.',state.integrations.proton,'Configured')}</div><div style="height:19px"></div><form id="settings-form" class="form-grid"><div class="field"><label for="apify-key">Apify API token</label><input id="apify-key" name="APIFY_API_TOKEN" type="password" autocomplete="new-password" placeholder="${state.integrations.apify?'Saved · enter new value to replace':'Add token'}" /></div><div class="field"><label for="nvidia-key">NVIDIA API key</label><input id="nvidia-key" name="NVIDIA_API_KEY" type="password" autocomplete="new-password" placeholder="${state.integrations.nvidia?'Saved · enter new value to replace':'Add key'}" /></div><div class="field"><label for="application-email">Application email</label><input id="application-email" name="APPLICATION_EMAIL" type="email" value="${esc(state.profile?.email||'')}" placeholder="name@proton.me" /></div><div class="field full"><button class="primary-button" type="submit">Save local settings</button></div></form><div style="height:22px"></div><h2>Proton Bridge mailbox</h2><p>Sign into Proton Mail Bridge on this Mac first. Use the local IMAP username, generated password, port, and security mode shown by Bridge.</p><form id="proton-form" class="form-grid"><div class="field"><label>Bridge IMAP host</label><input name="host" value="127.0.0.1" required /></div><div class="field"><label>Bridge IMAP port</label><input name="port" value="1143" inputmode="numeric" required /></div><div class="field"><label>Bridge SMTP port</label><input name="smtpPort" value="1025" inputmode="numeric" required /></div><div class="field"><label>Bridge security</label><select name="mode"><option value="starttls">STARTTLS</option><option value="ssl">SSL/TLS</option><option value="plain">Plain (Bridge setting)</option></select></div><div class="field"><label>Bridge username</label><input name="username" type="email" placeholder="Local Bridge username" required /></div><div class="field"><label>Bridge password</label><input name="password" type="password" autocomplete="new-password" required /></div><div class="field full button-row"><button class="primary-button" type="submit">Save in macOS Keychain</button><button class="secondary-button" type="button" data-action="proton-check">Check Bridge</button><button class="secondary-button" type="button" data-page="inbox">Open inbox</button></div></form><section class="mail-forward-settings"><h3>Forward application email</h3><p>Automatically forward new messages classified as application-related through Proton Bridge to your personal inbox. Existing messages are not forwarded. “Other” messages stay private until you relabel them.</p><form id="mail-forwarding-form"><div class="field"><label for="mail-forward-recipient">Personal inbox</label><input id="mail-forward-recipient" name="recipient" type="email" autocomplete="email" value="${esc(forwarding.recipient||'')}" placeholder="you@example.com" /></div><label class="inline-check"><input name="enabled" type="checkbox" ${forwarding.enabled?'checked':''}/> Automatically forward new application mail</label><p class="muted-line">Forwarded messages appear from Daymark using your application mailbox address. Messages are plain text; original attachments are preserved up to 20 MB. Mail content is never sent to NVIDIA.</p><button class="secondary-button" type="submit">Save forwarding settings</button></form></section><div style="height:22px"></div><h2>ATS sign-in passwords</h2><p>Save a default email and password for portals that ask you to sign in. Add an ATS hostname only when a site needs different credentials. Workday account setup, sign-in, email verification and password recovery use your saved credentials. CAPTCHA and unsupported identity checks pause for you. Other ATS account steps may need your input.</p><form id="ats-form" class="form-grid"><div class="field"><label>ATS hostname (optional)</label><input name="host" placeholder="Leave blank for default or enter boards.greenhouse.io" /></div><div class="field"><label>Username or email</label><input name="username" autocomplete="username" value="${esc(state.profile?.email||'')}" required /></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="new-password" required /></div><div class="field"><button class="primary-button" type="submit">Save ATS login</button></div></form><div class="inline-note">${svg('lock')} ATS credentials stay in a private local file and are never sent to NVIDIA. A portal-specific login overrides the default. Applications stop at final review. Submission requires a separate action. Workday password recovery stops if the employer requires a different password.</div></section>
<div class="page-grid"><section class="content-card"><h2>Daily job collection</h2><p>The selected Apify actor minimum is 200 results per run. Daymark adds at most 100 new jobs per day after filtering and deduplication.</p><div class="settings-list"><div class="setting-row"><div><strong>Collection frequency</strong><p>One collection run per day while your Mac is awake.</p></div><span class="source-badge">DAILY</span></div><div class="setting-row"><div><strong>New jobs added per day</strong><p>Maximum imported after matching and duplicate checks.</p></div><span class="source-badge">100 MAX</span></div><div class="setting-row"><div><strong>Application preparation</strong><p>One role at a time. Tailoring uses one model call; form filling is local.</p></div><span class="source-badge">SEQUENTIAL</span></div><div class="setting-row"><div><strong>Browser fill</strong><p>Uses supported adapters and DOM access. Submission follows verified automated checks.</p></div><span class="source-badge">REVIEW</span></div></div></section><aside><section class="content-card"><h2>Local by design</h2><p>Your dashboard and records run on this Mac.</p><div class="privacy-note">${svg('lock')} Resume files and ATS credentials stay in the local data folder. Proton Bridge login uses macOS Keychain.</div></section></aside></div>`}
function bindPageActions(){
  document.querySelectorAll('.field').forEach((field,index)=>{const label=field.querySelector('label'),input=field.querySelector('input,textarea,select');if(label&&input&&!label.htmlFor){input.id ||= `field-${index}-${input.name||'value'}`;label.htmlFor=input.id;}});

  $('#job-search')?.addEventListener('input',event=>{state.jobFilters.search=event.target.value;state.jobPage=1;refreshJobResults()});
  document.querySelectorAll('[data-job-filter]').forEach(input=>input.addEventListener(input.tagName==='INPUT'?'input':'change',event=>{state.jobFilters[input.dataset.jobFilter]=event.target.value;state.jobPage=1;if(input.tagName==='INPUT')refreshJobResults();else render()}));
  document.querySelectorAll('[data-clear-filter]').forEach(button=>button.onclick=()=>{state.jobFilters[button.dataset.clearFilter]='';state.jobPage=1;render()});
  document.querySelectorAll('[data-page]').forEach(button=>button.onclick=event=>{event.preventDefault();navigate(button.dataset.page)});
  bindCardActions();
  document.querySelectorAll('[data-job]').forEach(row=>row.addEventListener('click',e=>{if(!e.target.closest('button'))openJob(row.dataset.job)}));
  $('[data-action="collect"]')?.addEventListener('click',collect);
  $('[data-action="import-job"]')?.addEventListener('click',importJob);
  $('[data-action="profile"]')?.addEventListener('click',()=>navigate('profile'));
  $('[data-action="add-answer"]')?.addEventListener('click',()=>$('#answer-dialog').showModal());


  $('#answer-pack-form')?.addEventListener('submit',saveAnswerPack);
  $('[data-action="bridge-info"]')?.addEventListener('click',()=>toast('Install Proton Mail Bridge, sign in on this Mac, and add the Bridge local connection in Settings.'));
  $('#profile-form')?.addEventListener('submit',saveProfile);
  $('#resume-file')?.addEventListener('change',uploadResume);
  $('[data-action="reparse"]')?.addEventListener('click',()=>{if(confirm('Send your saved resume text to NVIDIA to map it into the master template?'))parseResumeRequest('/api/profile/resume/reparse',{sendToNvidia:true})});
  $('[data-action="improve-parse"]')?.addEventListener('click',()=>{if(confirm('Send your saved resume text to NVIDIA to improve extraction? Credentials, mailbox content, and application answers are not included.'))parseResumeRequest('/api/profile/resume/improve',{sendToNvidia:true})});
  $('[data-action="paste-resume"]')?.addEventListener('click',()=>{const text=prompt('Paste your resume text. It will be parsed and stored on this Mac.');if(text&&confirm('Send this resume text to NVIDIA to map it into your master template and profile?'))parseResumeRequest('/api/profile/resume/text',{text,sendToNvidia:true})});
  document.querySelectorAll('[data-setup-step]').forEach(button=>button.addEventListener('click',()=>changeSetupStep(button.dataset.setupStep)));
  $('[data-action="finish-setup"]')?.addEventListener('click',finishSetup);

  document.querySelectorAll('[data-keep-field]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.keepField;$(`#profile-${key}`).value=state.profile[key]||''}));
  document.querySelectorAll('[data-review-task]').forEach(button=>button.addEventListener('click',()=>openResumeReview(button.dataset.reviewTask)));
  $('#resume-review-form')?.addEventListener('submit',approveResumeReview);
  document.querySelectorAll('[data-check-service]').forEach(button=>button.addEventListener('click',()=>checkConnection(button)));
  $('#settings-form')?.addEventListener('submit',saveSettings);
  $('#mail-forwarding-form')?.addEventListener('submit',saveForwarding);
  $('#proton-form')?.addEventListener('submit',saveProton);
  $('#ats-form')?.addEventListener('submit',saveAtsCredential);
  $('[data-action="proton-check"]')?.addEventListener('click',checkProton);
  $('[data-action="mail-refresh"]')?.addEventListener('click',loadMail);
  $('#answer-form')?.addEventListener('submit',saveAnswer);
  document.querySelectorAll('[data-task-action]').forEach(btn=>btn.addEventListener('click',()=>taskAction(btn.dataset.id,btn.dataset.taskAction)));
  document.querySelectorAll('[data-job-answer]').forEach(button=>button.addEventListener('click',()=>draftJobAnswer(button.dataset.jobAnswer)));
  document.querySelectorAll('[data-fill-task]').forEach(btn=>btn.addEventListener('click',()=>fillTask(btn.dataset.fillTask)));
}
function navigate(page){if(!pageNames[page])return;if($('#assistant-dialog')?.open)$('#assistant-dialog').close();state.page=page;history.replaceState({},'',page==='processing'?`#application/${encodeURIComponent(state.processingJobId)}`:`#${page}`);render();closeMobileNav();window.scrollTo(0,0);$('#page-wrap').focus({preventScroll:true});if(page==='inbox')loadMail()}
function closeMobileNav({restoreFocus=false}={}){const sidebar=$('#sidebar'),toggle=$('#menu-toggle');sidebar.classList.remove('open');sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');$('.main-area').inert=false;document.body.classList.remove('nav-open');$('#nav-backdrop').classList.remove('visible');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');if(restoreFocus)toggle.focus()}
function openJob(id){const job=state.jobs.find(item=>item.id===id);if(!job)return;const dialog=$('#job-dialog');dialog.innerHTML=`<div class="dialog-head"><div><h2>${esc(job.role)}</h2><p>${esc(job.company)} · ${esc(job.location)}</p></div>${iconButton('close','Close dialog','data-close-dialog')}</div><div class="dialog-body"><h3>Posting details</h3><p>${esc(job.location||'Location not listed')} · ${esc(jobDate(job)?new Date(jobDate(job)).toLocaleDateString():'Date not recorded')}</p><p>This ${esc(job.source)} listing was matched to your search preferences. Review the original posting before preparing your materials.</p><h3>Why it may fit</h3><div class="match-wrap"><span class="match-ring" style="--p:${job.match}"><span>${job.match}</span></span><span>${job.match>=90?'Strong match for your profile':'Relevant experience and skills may align'}</span></div><div class="dialog-tags">${(job.tags||[]).map(t=>`<span class="skill-tag">${esc(t)}</span>`).join('')}</div><h3>Compensation</h3><p>${esc(job.salary||'Not provided in the listing')}</p>${job.companyWebsite?`<p><a href="${esc(job.companyWebsite)}" target="_blank" rel="noreferrer">Company website ↗</a></p>`:''}<h3>Job description</h3><p class="expanded-job-description">${esc(job.description||'No description available')}</p></div><div class="dialog-foot"><span class="muted-line">${esc(job.source)} · ${esc(job.posted||'Recently found')}</span><div class="button-row"><a class="secondary-button" href="${esc(job.url)}" target="_blank" rel="noreferrer">Open posting ${svg('arrow')}</a><button class="text-button" data-manual-job="${esc(job.id)}">Already applied? Update status</button><button class="primary-button" data-prepare="${esc(job.id)}">Apply · add to queue</button></div></div>`;dialog.showModal();dialog.querySelector('[data-close-dialog]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-prepare]').addEventListener('click',()=>createTask(job.id));dialog.querySelector('[data-manual-job]').onclick=()=>{dialog.close();state.processingJobId=job.id;navigate('processing');};}
$('#job-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});
async function createTask(jobId){if(!confirm('Start this application? The pilot tailors locally by prioritizing existing resume bullets without adding qualifications. It fills supported employer forms, handles recognized sign-in and verification, and stops for your final approval. It does not generate a cover letter.'))return;try{const result=await api('/api/tasks',{method:'POST',body:JSON.stringify({jobId,sendToNvidia:true,autoFill:true,stopAtFinalReview:true})});state.tasks=[result.task,...state.tasks.filter(task=>task.id!==result.task.id)];$('#job-dialog').close();render();toast('Added to the background queue. It will stop at final review.')}catch(error){toast(error.message,true)}}
async function fillTask(taskId){try{const result=await api('/api/tasks/fill',{method:'POST',body:JSON.stringify({taskId})});state.tasks=[result.task,...state.tasks.filter(task=>task.id!==result.task.id)];render();toast('Form fill queued in the background.')}catch(error){toast(error.message,true)}}
function canSubmitFromReview(task){const fill=applicationRun(state.tasks,task.jobId).fill;return Boolean(fill?.authStatus==='authenticated'&&fill.finalReviewReady&&!fill.submitAttemptedAt&&fill.status==='needs_you');}
const sourceLabels={profile:'Profile','answer pack':'Answer pack',library:'Learned',ai:'AI drafted',you:'You',autofill:'Form autofill',pay:'Pay policy'};
function filledAnswersPanel(fill){const steps=fill?.filledSteps||[],fields=fill?.fieldsFilled||[],receipt=fill?.receipt;if(!steps.length&&!fields.length)return '';return `<section class="filled-answers"><h3>Application receipt</h3>${receipt?`<p class="receipt-summary"><b>${receipt.filled}</b> fields filled · <b>${receipt.skipped.length}</b> skipped · <b>${receipt.generic||0}</b> generic answers · <b>${receipt.ai}</b> AI-drafted${fill.activeSeconds?` · agent time ${fill.activeSeconds<90?fill.activeSeconds+'s':Math.round(fill.activeSeconds/60)+' min'}`:''}</p>`:''}<p class="muted-line">Check these against the employer form before you submit.</p>${steps.map(step=>`<details open><summary>${esc(step.step)} · ${step.answers.length} answer${step.answers.length===1?'':'s'}</summary><dl>${step.answers.map(answer=>`<div><dt>${esc(answer.label)}</dt><dd>${esc(answer.value)}${answer.source?` <em class="src src-${esc(answer.source.replace(' ','-'))}">${esc(sourceLabels[answer.source]||answer.source)}</em>`:''}${['ai','library','autofill'].includes(answer.source)?` <button type="button" class="text-button fix-answer" data-fix-label="${esc(answer.label)}" data-fix-value="${esc(answer.value)}">Fix for next time</button>`:''}</dd></div>`).join('')}</dl></details>`).join('')}${receipt?.skipped?.length?`<details><summary>Skipped optional questions (${receipt.skipped.length})</summary><p>${receipt.skipped.map(esc).join(' · ')}</p></details>`:''}</section>`;}
function openResumeReview(taskId,inline=null){const task=state.tasks.find(item=>item.id===taskId);if(!task?.review)return;const review=task.review,dialog=inline||$('#job-dialog');const prior=new Set((review.approvedAdditions||[]).map(item=>`${item.category}:${item.content}`));const suggestions=(review.proposedAdditions||[]).map((item,index)=>({...item,index})).filter(item=>!prior.has(`${item.category}:${item.content}`));dialog.innerHTML=`<div class="dialog-head"><div><p class="eyebrow">${esc(task.company)} · ${esc(task.role)}</p><h2>Final application review</h2><p>Edit the draft and review the print preview. Select a suggestion only when it accurately describes your experience.</p></div><button class="icon-button" type="button" aria-label="Close resume review" data-close-review>${svg('close')}</button></div><form id="resume-review-form" data-task-id="${esc(taskId)}"><div class="dialog-body">${filledAnswersPanel(applicationRun(state.tasks,task.jobId).fill)}<div class="resume-review-layout"><div class="field"><label for="review-resume-text">Resume draft</label><textarea id="review-resume-text" name="resumeText" rows="24" required>${esc(review.resume||'')}</textarea><small>Names, client details, employers, titles, dates, and contact details from your confirmed profile must stay unchanged.</small></div><div class="field"><span class="preview-label">Live document preview</span><iframe id="resume-review-preview" class="resume-preview-frame" title="Formatted resume preview" sandbox></iframe></div></div>${suggestions.length?`<section class="suggestion-list"><h3>Optional suggestions</h3><p>Suggestions start unchecked and stay out of the resume unless you confirm them. Project ideas require a separate completion confirmation.</p>${suggestions.map(item=>`<div class="suggestion-block"><label class="suggestion-card"><input type="checkbox" name="suggestion" value="${item.index}"/><span><strong>${esc(item.category.replaceAll('_',' '))}</strong><span>${esc(item.content)}</span><small>${esc(item.jobRequirement||item.whyItMayHelp||'Suggested for this role')} · AI suggestion</small></span></label>${item.category==='project_idea'?`<label class="project-attestation"><input type="checkbox" name="completedProject" value="${item.index}"/>I have completed this project.</label>`:''}</div>`).join('')}</section>`:''}${review.approvedAdditions?.length?`<details class="change-log"><summary>Confirmed model suggestions (${review.approvedAdditions.length})</summary>${review.approvedAdditions.map(item=>`<div class="change-entry"><strong>${esc(item.category.replaceAll('_',' '))}</strong><span class="source-status">Suggested by AI · confirmed by you</span><p>${esc(item.content)}</p>${item.jobRequirement?`<p><span>Role requirement</span> ${esc(item.jobRequirement)}</p>`:''}</div>`).join('')}</details>`:''}${review.changes?.length?`<details class="change-log"><summary>View ${review.changes.length} source-backed tailoring changes</summary>${review.changes.map(change=>`<div class="change-entry"><strong>${esc(change.section||'Resume')}</strong><span class="source-status ${change.sourceStatus==='needs_confirmation'?'needs-confirmation':''}">${change.sourceStatus==='needs_confirmation'?'Source needs your review':change.sourceStatus==='user_confirmed'?'Confirmed by you':change.sourceStatus==='user_reviewed'?'Edited by you':'Source excerpt checked'}</span><p>${esc(change.reason||'Aligned content to this role.')}</p>${change.before?`<p><span>Before</span> ${esc(change.before)}</p>`:''}<p><span>After</span> ${esc(change.after)}</p>${change.sourceExcerpt?`<p><span>Source</span> ${esc(change.sourceExcerpt)}</p>`:''}</div>`).join('')}</details>`:''}<details class="cover-letter-preview"><summary>Preview cover letter</summary><p>${esc(review.coverLetter||'')}</p></details><p class="review-error" id="resume-review-error" role="alert"></p><label class="review-confirm"><input type="checkbox" name="confirmedAccurate" required/><span>I reviewed the resume and confirm its claims, including any source flags or selected suggestions, accurately describe my background.</span></label></div><div class="dialog-foot"><span class="muted-line">${review.approvalStatus==='approved'?'Saving creates a new reviewed version.':'Approve once, then submit from the application page.'}</span>${canSubmitFromReview(task)?`<button class="secondary-button" type="submit">${review.approvalStatus==='approved'?'Save without submitting':'Approve without submitting'}</button><button class="primary-button" type="submit" data-submit-after="1">Approve &amp; submit application ${svg('arrow')}</button>`:`<button class="primary-button" type="submit">${review.approvalStatus==='approved'?'Save reviewed version':'Approve final application materials'}</button>`}</div></form>`;if(!inline)dialog.showModal();const close=dialog.querySelector('[data-close-review]');if(inline)close.remove();else close.onclick=()=>dialog.close();const textArea=$('#review-resume-text');if(inline)textArea.rows=12;textArea.value=state.reviewDrafts[taskId]??review.resume;const updatePreview=()=>{state.reviewDrafts[taskId]=textArea.value;$('#resume-review-preview').srcdoc=resumePreviewDocument(textArea.value);};textArea.addEventListener('input',updatePreview);updatePreview();}
async function approveResumeReview(event){event.preventDefault();const form=event.currentTarget,taskId=form.dataset.taskId,buttons=[...form.querySelectorAll('[type="submit"]')],submitAfter=event.submitter?.dataset.submitAfter==='1',error=$('#resume-review-error');buttons.forEach(item=>item.disabled=true);error.textContent='Saving your reviewed resume…';const chosen=[...form.querySelectorAll('input[name="suggestion"]:checked')].map(input=>Number(input.value));const completedProjects=[...form.querySelectorAll('input[name="completedProject"]:checked')].map(input=>Number(input.value));try{const result=await api(`/api/tasks/${taskId}/review`,{method:'POST',body:JSON.stringify({resumeText:form.elements.resumeText.value,acceptedSuggestionIndices:chosen,completedProjects,confirmedAccurate:form.elements.confirmedAccurate.checked,submitAfter})});state.tasks=state.tasks.map(task=>task.id===taskId?result.task:task);if(result.fillTask)state.tasks=[result.fillTask,...state.tasks.filter(task=>task.id!==result.fillTask.id)];$('#job-dialog').close();delete state.reviewDrafts[taskId];render();toast(result.fillMessage||'Final review saved. Your reviewed documents are ready.')}catch(cause){error.textContent=cause.message;buttons.forEach(item=>item.disabled=false)}}
async function collect(){if(!state.integrations.apify){toast('Add your Apify token in Settings to connect live postings.');return navigate('settings')}try{await api('/api/collect',{method:'POST',body:'{}'})}catch(error){toast(error.message,true)}}
async function importJob(){if(state.page!=='jobs')navigate('jobs');$('#import-role-url')?.focus();}
async function importRole(event){event.preventDefault();const form=event.currentTarget,input=form.elements.url,button=form.querySelector('button'),status=form.querySelector('[role="status"]');if(state.importing)return;state.importing=true;state.importLinkDraft=input.value;button.disabled=true;status.textContent='Fetching posting details…';try{const {job}=await api('/api/jobs/import',{method:'POST',body:JSON.stringify({url:input.value})});state.jobs=[job,...state.jobs.filter(item=>item.id!==job.id)];state.importedJob=job;state.importLinkDraft='';state.importing=false;state.jobPage=1;refreshJobResults();toast('Posting imported. Review its card below.');}catch(error){status.textContent=error.message;}finally{state.importing=false;button.disabled=false;}}

async function saveProfile(event){event.preventDefault();clearTimeout(resumeDraftTimer);const form=event.currentTarget;const {fields,document}=profileEditorBody(form);try{await resumeDraftSave.catch(()=>{});const result=await api('/api/profile',{method:'POST',body:JSON.stringify({...fields,...(document?{document}:{})})});state.profile=result.profile;state.resumeDraft=null;await refreshSetupStatus();await changeSetupStep('answers');toast('Master resume confirmed and saved.')}catch(error){$('#profile-error').textContent=error.message}}
async function uploadResume(event){const file=event.target.files[0];if(!file)return;if(!confirm('Send the text of this resume to NVIDIA to map it into your master template and profile? Passwords and mailbox content are excluded.')){event.target.value='';return}try{await parseResumeRequest('/api/profile/resume',{name:file.name,type:file.type,data:await fileToBase64(file),sendToNvidia:true})}catch(error){toast(error.message,true)}}
async function parseResumeRequest(url,body){const status=$('#resume-status');if(status)status.textContent='Reading your resume and mapping it with NVIDIA…';document.querySelectorAll('[data-action="reparse"],[data-action="improve-parse"],#resume-file').forEach(x=>x.disabled=true);try{const result=await api(url,{method:'POST',body:JSON.stringify(body)});state.resumeDraft=result.draft;state.onboarding=result.onboarding;state.profile.resumeName=result.resumeName;state.profile.resumeText='[saved locally]';await refreshSetupStatus();render();toast('Master resume draft created. Review your profile fields.')}catch(error){if(status)status.textContent='Parsing needs your attention.';$('#profile-error').textContent=error.message}finally{document.querySelectorAll('[data-action="reparse"],[data-action="improve-parse"],#resume-file').forEach(x=>x.disabled=false)}}
async function changeSetupStep(step){try{const result=await api('/api/onboarding',{method:'POST',body:JSON.stringify({step})});state.onboarding=result.onboarding;navigate('setup')}catch(error){toast(error.message,true)}}
async function finishSetup(){try{await refreshSetupStatus();if(!state.setup?.ready){render();return toast('Complete all required setup items first.',true)}const result=await api('/api/onboarding',{method:'POST',body:JSON.stringify({step:'ready',completed:true})});Object.assign(state,result);navigate('home')}catch(error){toast(error.message,true)}}
async function refreshSetupStatus(){const data=await api('/api/state');state.setup=data.setup;state.integrations=data.integrations;state.onboarding=data.onboarding;state.resumeDraft=data.resumeDraft||null;state.profile=data.profile;state.answerPack=data.answerPack;state.mailForwarding=data.mailForwarding||state.mailForwarding;state.worker=data.worker;}
async function checkConnection(button){button.disabled=true;const status=$(`#check-${button.dataset.checkService}`);status.textContent='Checking…';try{const result=await api('/api/connections/check',{method:'POST',body:JSON.stringify({service:button.dataset.checkService})});state.connectionChecks=result.connectionChecks;status.textContent=result.message}catch(error){status.textContent=error.message}finally{button.disabled=false}}
function fileToBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('Could not read the selected file.'));reader.readAsDataURL(file)})}
async function saveSettings(event){event.preventDefault();const body=Object.fromEntries(new FormData(event.currentTarget));try{const result=await api('/api/settings',{method:'POST',body:JSON.stringify(body)});state.integrations={...state.integrations,...result.configured};if(body.APPLICATION_EMAIL){state.profile={...state.profile,email:body.APPLICATION_EMAIL};}await refreshSetupStatus();render();toast('Local settings saved.')}catch(error){toast(error.message,true)}}
async function saveForwarding(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),body={recipient:form.elements.recipient.value.trim(),enabled:form.elements.enabled.checked};button.disabled=true;try{const result=await api('/api/mail/forwarding',{method:'POST',body:JSON.stringify(body)});state.mailForwarding={...state.mailForwarding,...result.forwarding};toast(body.enabled?'Automatic application email forwarding enabled.':'Automatic email forwarding paused.');render()}catch(error){toast(error.message,true)}finally{button.disabled=false}}
async function saveAnswer(event){event.preventDefault();const body=Object.fromEntries(new FormData(event.currentTarget));try{const result=await api('/api/answers',{method:'POST',body:JSON.stringify(body)});state.answers.unshift(result.answer);render();toast('Answer saved.')}catch(error){toast(error.message,true)}}
async function saveAnswerPack(event){event.preventDefault();const form=new FormData(event.currentTarget);const values={};for(const question of questionCatalog)values[question.id]=question.multiple?form.getAll(question.id):form.get(question.id)||'';values.startDate=form.get('startDate')||'';for(const question of eeoQuestionCatalog)values[question.id]=form.get(question.id)||'';try{const result=await api('/api/answer-pack/setup',{method:'POST',body:JSON.stringify({values,completed:event.submitter?.value==='complete'})});state.answerPack=result.answerPack;state.answerPackSetup=result.answerPackSetup;state.onboarding=result.onboarding;await refreshSetupStatus();navigate('setup');toast('Your choices are saved on this Mac.')}catch(error){$('#answer-pack-error').textContent=error.message}}
async function saveProton(event){event.preventDefault();const body=Object.fromEntries(new FormData(event.currentTarget));try{await api('/api/proton/configure',{method:'POST',body:JSON.stringify(body)});await refreshSetupStatus();render();toast('Bridge password saved in macOS Keychain.')}catch(error){toast(error.message,true)}}
async function checkProton(){try{const result=await api('/api/proton/check',{method:'POST',body:'{}'});toast(`Bridge connected · ${result.recentMessages} messages in Inbox.`)}catch(error){toast(error.message,true)}}
async function loadMail(){return refreshMailbox();}
async function saveAtsCredential(event){event.preventDefault();const body=Object.fromEntries(new FormData(event.currentTarget));try{await api('/api/ats-credentials',{method:'POST',body:JSON.stringify(body)});await refreshSetupStatus();render();toast(`ATS login saved locally${body.host?` for ${body.host}`:' as the default'}.`)}catch(error){toast(error.message,true)}}
async function taskAction(id,action){try{const {task}=await api(`/api/tasks/${id}/${action}`,{method:'POST',body:'{}'});state.tasks=state.tasks.map(t=>t.id===id?task:t);render();toast(action==='cancel'?'Task removed.':action==='pause'?'Task paused.':'Task resumed.')}catch(error){toast(error.message,true)}}
async function loadState(){try{const data=await api('/api/state');Object.assign(state,data);const routes={'#home':'home','#jobs':'jobs','#autoApply':'autoApply','#pipeline':'pipeline','#applications':'applications','#inbox':'inbox','#profile':'profile','#answers':'answers','#questions':'questions','#setup':'setup','#settings':'settings'};if(!state.onboarding?.completed)state.page='setup';else if(location.hash.startsWith('#application/')){state.processingJobId=decodeURIComponent(location.hash.slice(13));state.page='processing';}else state.page=routes[location.hash]||'home';render();if(state.page==='inbox')loadMail()}catch(error){$('#page-wrap').innerHTML=`<div class="page-heading"><div><div class="eyebrow">LOCAL SERVER</div><h1>Daymark couldn’t connect.</h1><p>${esc(error.message)} Restart the app with <span class="mono">npm start</span>.</p></div></div>`}}
$('#assistant-form').addEventListener('submit',event=>{event.preventDefault();const input=$('#assistant-input'),message=input.value.trim();input.value='';sendAssistantMessage(message)});
document.querySelectorAll('[data-assistant-prompt]').forEach(button=>button.addEventListener('click',()=>sendAssistantMessage(button.dataset.assistantPrompt)));
let assistantReturnFocus=null;
function openAssistant(){assistantReturnFocus=document.activeElement;$('#assistant-dialog').showModal();$('#assistant-input').focus()}
$('#assistant-open').addEventListener('click',openAssistant);
$('#assistant-open-top').addEventListener('click',openAssistant);
$('.assistant-close').addEventListener('click',()=>$('#assistant-dialog').close());
$('#assistant-dialog').addEventListener('click',event=>{if(event.target===event.currentTarget)event.currentTarget.close()});
$('#assistant-dialog').addEventListener('close',()=>{const target=assistantReturnFocus?.isConnected?assistantReturnFocus:$('#assistant-open-top');target.focus();assistantReturnFocus=null});
$('#mobile-nav-close').addEventListener('click',()=>closeMobileNav({restoreFocus:true}));
$('#menu-toggle').addEventListener('click',()=>{const open=!$('#sidebar').classList.contains('open'),sidebar=$('#sidebar');sidebar.classList.toggle('open',open);$('#nav-backdrop').classList.toggle('visible',open);$('.main-area').inert=open;document.body.classList.toggle('nav-open',open);if(open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true')}else{sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal')}$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');if(open)$('#sidebar .nav-item').focus()});
document.addEventListener('click',e=>{if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle'))closeMobileNav({restoreFocus:true})});
document.addEventListener('keydown',e=>{if(!$('#sidebar').classList.contains('open'))return;if(e.key==='Escape'){e.preventDefault();closeMobileNav({restoreFocus:true});return}if(e.key==='Tab'){const items=[...$('#sidebar').querySelectorAll('button:not([disabled]),a[href]')].filter(item=>item.offsetParent!==null);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('resize',()=>{if(window.innerWidth>1100&&$('#sidebar').classList.contains('open'))closeMobileNav()});
configureMailbox({api:(path,options)=>api(path,options),toast,navigate,routing:()=>({mailRouting:state.mailRouting||{},applications:state.routingTargets||state.applications}),onRouting:data=>{if(data.mailRouting)state.mailRouting=data.mailRouting;if(data.applications)state.applications=data.applications;if(data.routingTargets)state.routingTargets=data.routingTargets;}});
document.addEventListener('change',async event=>{const ai=event.target.closest?.('[data-pref-ai]');if(ai){const next=ai.checked;try{const result=await api('/api/preferences',{method:'POST',body:JSON.stringify({aiAnswers:next})});state.preferences=result.preferences;toast(next?'AI-drafted answers are on for open-ended questions.':'AI-drafted answers are off. Open-ended questions will wait for you.')}catch(error){ai.checked=!next;toast(error.message,true)}return;}const box=event.target.closest?.('[data-pref-review]');if(!box)return;const next=box.checked;try{const result=await api('/api/preferences',{method:'POST',body:JSON.stringify({reviewBeforeSubmit:next})});state.preferences=result.preferences;refreshStream();toast(next?'Applications will wait for your review before submitting.':'Submission remains a separate action.')}catch(error){box.checked=!next;toast(error.message,true)}});
document.addEventListener('submit',async event=>{const auto=event.target.closest?.('#automation-form');if(auto){event.preventDefault();const f=new FormData(auto);if(f.get('enabled')==='on'&&state.preferences?.autoApply?.enabled===false&&!confirm(`Enable automatic application preparation? Daymark can queue up to ${f.get('dailyCap')} roles per day. Daymark will stop at final review and wait for a separate submit action.`))return;try{const result=await api('/api/preferences',{method:'POST',body:JSON.stringify({autoApply:{enabled:f.get('enabled')==='on',minMatch:Number(f.get('minMatch')),dailyCap:Number(f.get('dailyCap'))},skipRules:{clearance:f.get('clearance')==='on',remoteOnly:f.get('remoteOnly')==='on',minSalary:Number(f.get('minSalary')||0),excludedCompanies:String(f.get('excludedCompanies')||''),excludedTitles:String(f.get('excludedTitles')||'')},defaults:{resumeMode:f.get('resumeMode'),coverLetter:f.get('coverLetter')}})});state.preferences=result.preferences;$('#automation-status').textContent='Saved.'}catch(error){$('#automation-status').textContent=error.message}return;}const details=event.target.closest?.('#application-details-form');if(details){event.preventDefault();try{const result=await api('/api/profile/application-details',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(details)))});state.profile=result.profile;$('#application-details-status').textContent='Saved.'}catch(error){$('#application-details-status').textContent=error.message}return;}const entry=event.target.closest?.('[data-library-label]');if(entry){event.preventDefault();try{const result=await api('/api/answer-library',{method:'POST',body:JSON.stringify({label:entry.dataset.libraryLabel,answer:new FormData(entry).get('answer')})});state.applicationAnswerPack=result.applicationAnswerPack;toast('Learned answer updated.')}catch(error){toast(error.message,true)}}});
document.addEventListener('change',async event=>{const option=event.target.closest?.('[data-task-option]');if(!option)return;try{const result=await api(`/api/tasks/${option.dataset.task}/options`,{method:'POST',body:JSON.stringify({[option.dataset.taskOption]:option.value})});state.tasks=state.tasks.map(task=>task.id===result.task.id?result.task:task);toast('Application option saved.')}catch(error){toast(error.message,true);render()}});
document.addEventListener('click',async event=>{const all=event.target.closest?.('[data-submit-all]');if(all){all.disabled=true;try{const preview=await api('/api/tasks/submit-all',{method:'POST',body:JSON.stringify({})});if(!preview.eligible.length){toast(preview.held.length?`Nothing can be bulk-submitted: ${preview.held.map(h=>h.label+' ('+h.reason+')').join('; ')}`:'No applications are ready to submit.',!preview.held.length?false:true);return;}if(!confirm(`Submit these ${preview.eligible.length} reviewed applications now?\n\n${preview.eligible.join('\n')}${preview.held.length?`\n\nHeld back:\n${preview.held.map(h=>h.label+' — '+h.reason).join('\n')}`:''}`))return;const result=await api('/api/tasks/submit-all',{method:'POST',body:JSON.stringify({confirmed:true})});toast(`${result.queued.length} application${result.queued.length===1?'':'s'} queued for submission.`)}catch(error){toast(error.message,true)}finally{all.disabled=false}return;}const fix=event.target.closest?.('.fix-answer');if(fix){try{const result=await api('/api/answer-library/add',{method:'POST',body:JSON.stringify({label:fix.dataset.fixLabel,answer:fix.dataset.fixValue})});state.applicationAnswerPack=result.applicationAnswerPack;navigate('answers');toast('Edit this answer under Learned answers. It will be used next time.')}catch(error){toast(error.message,true)}return;}const clear=event.target.closest?.('[data-clear-submit]');if(clear){if(!confirm('Only continue if the employer page and your inbox show no application for this role. Daymark will then be allowed to submit it again.'))return;clear.disabled=true;try{await api('/api/tasks/clear-submit',{method:'POST',body:JSON.stringify({taskId:clear.dataset.clearSubmit,confirmed:true})});toast('Retry allowed. Choose Continue processing to refill and submit again.');await loadState()}catch(error){toast(error.message,true);clear.disabled=false}return;}const tab=event.target.closest?.('[data-app-tab]');if(tab){state.jobFilters.status=tab.dataset.appTab;state.jobPage=1;render();return;}const del=event.target.closest?.('[data-library-delete]');if(del){const entry=del.closest('[data-library-label]');try{const result=await api('/api/answer-library/delete',{method:'POST',body:JSON.stringify({label:entry.dataset.libraryLabel})});state.applicationAnswerPack=result.applicationAnswerPack;render();toast('Learned answer removed.')}catch(error){toast(error.message,true)}return;}const one=event.target.closest?.('[data-submit-task]');if(one){if(state.workspaceDraftDirty){toast('Save and recheck your changes before submitting.',true);return;}one.disabled=true;try{await api('/api/tasks/submit',{method:'POST',body:JSON.stringify({taskId:one.dataset.submitTask,confirmed:true})});toast('Submitting your application…')}catch(error){toast(error.message,true);one.disabled=false}}});
setInterval(()=>{document.querySelectorAll('[data-stream-clock]').forEach(node=>{const since=Number(node.dataset.since);node.textContent=formatClock(since?Date.now()-since:0)})},1000);
loadState();setInterval(async()=>{try{const data=await api('/api/state');const changed=JSON.stringify(state.tasks)!==JSON.stringify(data.tasks)||JSON.stringify(state.jobs)!==JSON.stringify(data.jobs)||JSON.stringify(state.applications)!==JSON.stringify(data.applications);state.tasks=data.tasks;state.integrations=data.integrations;state.setup=data.setup;state.jobs=data.jobs;state.applications=data.applications;state.lastCollection=data.lastCollection;state.preferences=data.preferences;state.mailEvents=data.mailEvents;state.mailRouting=data.mailRouting;if(changed){state.cardRefreshPending=true;state.processingRefreshPending=true;state.streamRefreshPending=true;state.refreshPending=true;}if(state.cardRefreshPending)state.cardRefreshPending=updateCardActivities();if(state.processingRefreshPending&&state.page==='processing')state.processingRefreshPending=updateProcessing();if(state.streamRefreshPending)state.streamRefreshPending=refreshStream();const page=$('#page-wrap'),hasPageFocus=page?.contains(document.activeElement)&&document.activeElement!==page,blockingDialog=state.page==='processing'?page?.querySelector('dialog[open]'):document.querySelector('dialog[open]'),canRefresh=!state.importing&&!blockingDialog&&!hasPageFocus&&!page?.querySelector('details[open]');if(state.refreshPending&&canRefresh&&['home','jobs','applications','pipeline','autoApply','processing','questions'].includes(state.page)){render();state.refreshPending=false}}catch{}},2500);

async function draftJobAnswer(id){const question=prompt('Enter the question from this application:');if(!question)return;if(!confirm('Send this question, the job description, and this application’s tailored resume to NVIDIA? You will review the draft before using it.'))return;try{const result=await api(`/api/tasks/${id}/answer`,{method:'POST',body:JSON.stringify({question,sendToNvidia:true})});const dialog=$('#job-dialog');dialog.innerHTML=`<div class="dialog-head"><h2>Review application answer</h2><button class="icon-button" aria-label="Close" id="close-answer">${svg('close')}</button></div><div class="dialog-body"><h3>${esc(question)}</h3><p class="source-excerpt">${esc(result.answer)}</p><details><summary>Supporting facts</summary><p class="source-excerpt">${esc(result.evidence)}</p></details><p>Saved with this application. Review and copy it into the form.</p></div>`;dialog.showModal();$('#close-answer').onclick=()=>dialog.close()}catch(error){toast(error.message,true)}}

function setupChecklist(){
  const setup=state.setup||{requirements:[],ready:false};
  return `<section class="setup-checklist content-card"><div class="section-title-row"><div><span class="eyebrow">WORKSPACE READINESS</span><h2>${setup.ready?'Everything is in place.':'A few details before you begin.'}</h2></div><span class="source-badge">${setup.requirements.filter(item=>item.complete).length}/${setup.requirements.length}</span></div><div class="readiness-list">${setup.requirements.map(item=>`<button class="readiness-item ${item.complete?'complete':''}" data-page="${item.page}"><span class="readiness-icon">${svg(item.complete?'check':item.id==='resume'?'file':item.id==='email'?'mail':'arrow')}</span><span>${esc(item.label)}</span><small>${item.complete?'Saved':'Complete this'}</small></button>`).join('')}</div><button class="primary-button" data-action="finish-setup" ${setup.ready?'':'disabled'}>Finish setup ${svg('arrow')}</button></section>`;
}
function companyLogo(job){
  const letter=esc((job.company||'?').trim().slice(0,1).toUpperCase());
  const url=String(job.logoUrl||'');
  let safe='';try{const parsed=new URL(url);if(parsed.protocol==='https:'&&!parsed.username&&!parsed.password)safe=parsed.href;}catch{}
  return `<span class="company-logo" data-logo-job="${esc(job.id)}" data-company="${esc(job.company||'Company')}"><span class="logo-fallback" aria-hidden="true">${letter}</span>${safe?`<img src="${esc(safe)}" alt="${esc(job.company)} logo" loading="lazy" referrerpolicy="no-referrer" data-company-logo/>`:''}</span>`;
}
function latestJobTask(job){return state.tasks.filter(task=>task.jobId===job.id&&task.type!=='collect').sort((a,b)=>Date.parse(b.updatedAt||b.createdAt||'')-Date.parse(a.updatedAt||a.createdAt||''))[0]}
function jobCard(job,{application=false}={}){
  const task=latestJobTask(job),status=jobStatus(job,state.tasks,state.applications),record=state.applications.find(item=>item.jobId===job.id||item.id===job.id);
  const date=jobDate(job);
  const run=applicationRun(state.tasks,job.id);
  const action=task?`<button class="${task.status==='ready_for_review'?'primary-button':'secondary-button'}" data-task-details="${esc(task.id)}">${run.finalReady&&!run.approved?'Final review':'View progress'} ${svg('arrow')}</button>`:record&&record.status!=='skipped'?`<button class="secondary-button" data-application-status="${esc(job.id)}">Update status</button>`:`<button class="primary-button" data-apply-job="${esc(job.id)}">Apply ${svg('arrow')}</button>`;

  return `<article class="job-card" data-card-job="${esc(job.id)}" data-card-history="${Boolean(job.historical)}"><div class="job-card-top">${companyLogo(job)}<div class="job-company"><strong>${esc(job.company||'Company not recorded')}</strong><span>${esc(job.source||job.ats||'Career site')}</span></div>${status!=='not_started'||record?`<span class="state-pill ${esc(status)}">${esc(applicationStatuses.find(([id])=>id===status)?.[1]||status.replaceAll('_',' '))}</span>`:''}</div><h3>${esc(job.role||'Role not recorded')}</h3>${cardExtras(job,record)}<div class="job-meta"><span>${svg('compass')}${esc(job.location||'Location not listed')}</span><span>${svg('briefcase')}${esc(job.salary||'Pay not listed')}</span></div>${(job.tags||[]).length?`<div class="dialog-tags">${job.tags.slice(0,3).map(tag=>`<span class="skill-tag">${esc(tag)}</span>`).join('')}</div>`:''}<div class="job-card-bottom"><span>${date?relativeDate(new Date(date).toISOString()):'Date not recorded'}${job.match!=null?` · ${Number(job.match)||0}% preference match`:''}</span>${job.historical?`<button class="text-button job-detail-link" data-history-job="${esc(job.id)}">Details</button>`:`<button class="text-button job-detail-link" data-open-job="${esc(job.id)}" aria-label="View details for ${esc(job.role)} at ${esc(job.company)}">Details</button>`}${action}</div>${task?`<div class="card-live-activity" data-live-job="${esc(job.id)}">${cardLiveActivity(job.id)}</div>`:''}</article>`;
}
function cardExtras(job,record){const prep=state.tasks.find(task=>task.type==='prepare'&&task.jobId===job.id&&!['cancelled','failed'].includes(task.status));let html='';if(record?.status==='skipped')html+=`<p class="skip-note">Skipped · ${esc(record.skipReason||'matched a skip rule')}<br/><small>Rule: ${esc(record.skipRule||'skip rule')} · Apply anyway to override.</small></p>`;if(prep&&prep.status==='queued')html+=`<div class="card-options"><label>Resume<select data-task-option="resumeMode" data-task="${esc(prep.id)}"><option value="tailored" ${prep.resumeMode!=='default'?'selected':''}>Tailored</option><option value="default" ${prep.resumeMode==='default'?'selected':''}>Default</option></select></label><label>Cover letter<select data-task-option="coverLetter" data-task="${esc(prep.id)}"><option value="on" ${prep.coverLetter!=='off'?'selected':''}>On</option><option value="off" ${prep.coverLetter==='off'?'selected':''}>Off</option></select></label></div>`;else if(prep)html+=`<p class="card-mode">Resume: ${prep.resumeMode==='default'?'Default':'Tailored'} · Cover letter: ${prep.coverLetter==='off'?'Off':'On'}${prep.source==='auto'?' · auto-applied':''}</p>`;return html;}
function cardLiveActivity(jobId){const run=applicationRun(state.tasks,jobId);const record=state.applications.find(item=>item.jobId===jobId);const recorded=record&&(record.manuallyUpdated&&!['in_progress','filled'].includes(record.status)||['submitted','screening','interview','offer','rejected','withdrawn'].includes(record.status));const statusLabel=applicationStatuses.find(([id])=>id===record?.status)?.[1]||record?.status;const percent=record?.manuallyUpdated&&record.status==='not_started'?0:record?.manuallyUpdated&&!['in_progress','filled','failed'].includes(record.status)?100:run.progress;return run.current?`<button class="card-progress-button" data-task-details="${esc(run.current.id)}" aria-label="Open live processing for ${esc(run.current.role)}"><span class="live-indicator ${!recorded&&['running','queued'].includes(run.current.status)?'active':''}" aria-hidden="true"></span><span><b>${esc(recorded?statusLabel:run.current.stage||({queued:'Queued',running:run.current.type==='prepare'?'Tailoring resume':'Filling information',failed:'Failed',needs_you:'Needs your answer',ready_for_review:'Final review'})[run.current.status]||'Paused')}</b><small>${esc(recorded?'Application status recorded locally.':displayTaskMessage(run.current.message||'Waiting for processing'))} · ${esc(relativeDate(run.current.updatedAt||run.current.createdAt))}</small></span><strong>${percent}%</strong><span class="card-progress-track"><i style="width:${percent}%"></i></span></button>`:'';}
function updateCardActivities(){let pending=false;document.querySelectorAll('[data-live-job]').forEach(region=>{if(region.contains(document.activeElement)){pending=true;return}region.innerHTML=cardLiveActivity(region.dataset.liveJob);bindCardActions(region)});return pending}
function streamPath(points){return points.map(([x,y],i)=>{if(!i)return `M${x} ${y}`;const [px,py]=points[i-1],mid=(px+x)/2;return `C${mid} ${py} ${mid} ${y} ${x} ${y}`}).join(' ')}
function streamSvg(model){
 const n=model.stages.length,width=680,xs=model.stages.map((_,i)=>56+i*(width-112)/(n-1)),ys=model.stages.map((_,i)=>i%2?62:128);
 const points=xs.map((x,i)=>[x,ys[i]]);
 const segments=points.slice(1).map((point,i)=>{const hot=['active'].includes(model.stages[i].status)||model.stages[i+1].status==='active';const done=model.stages[i].count&&model.stages[i+1].count;return `<path d="${streamPath([points[i],point])}" class="ls-line ${hot?'hot':done?'done':''}"/>`}).join('');
 const lowY=206,low=`<path d="${streamPath([points[0],[xs[Math.floor(n/2)],lowY],[xs[n-1],lowY-8]])}" class="ls-line faint"/><circle cx="${xs[Math.floor(n/2)]}" cy="${lowY}" r="5" class="ls-hollow"/><text x="${xs[Math.floor(n/2)]}" y="${lowY+20}" text-anchor="middle" class="ls-sub">${model.queued} queued</text><circle cx="${xs[n-1]}" cy="${lowY-8}" r="5" class="ls-hollow"/><text x="${xs[n-1]}" y="${lowY+12}" text-anchor="middle" class="ls-sub">${model.needsYou} need you</text>`;
 const nodes=model.stages.map((stage,i)=>{const [x,y]=points[i],r=stage.status==='idle'?7:stage.status==='active'?13:10,above=y<90,ly=above?y-r-22:y+r+18;return `<g class="ls-node ${stage.status}"><title>${esc(stage.label)}: ${esc(stage.sub)}</title>${stage.status==='active'||stage.status==='waiting'?`<circle cx="${x}" cy="${y}" r="${r+10}" class="ls-halo"/>`:''}<circle cx="${x}" cy="${y}" r="${r}" class="ls-dot"/><text x="${x}" y="${ly}" text-anchor="middle" class="ls-label">${esc(stage.label)}</text><text x="${x}" y="${ly+14}" text-anchor="middle" class="ls-sub">${esc(stage.sub)}</text></g>`}).join('');
 const summary=model.stages.map(s=>`${s.label} ${s.status}, ${s.sub}`).join('; ');
 return `<svg viewBox="0 0 ${width} 240" role="img" aria-label="Pipeline progress. ${esc(summary)}">${low}${segments}${nodes}</svg>`;
}
function executionStream(now=Date.now()){
 const model=streamModel(state,now),pct=model.batch.total?Math.round(model.batch.done/model.batch.total*100):0;
 const feed=model.events.length?model.events.map(item=>`<li class="ls-row ${item.badge.toLowerCase()}">${item.href?`<button type="button" class="ls-row-main" data-open-job-run="${esc(item.jobId||'')}" data-task-id="${esc(item.id)}" data-href="${esc(item.href)}">`:'<div class="ls-row-main">'}<time>${esc(relativeClock(item.at,now))}</time><i class="ls-dot-mark" aria-hidden="true"></i><span class="ls-text"><b>${esc(item.title)}</b><small>${esc(item.detail||'')}</small></span><em class="ls-badge">${esc(item.badge)}</em>${item.href?'</button>':'</div>'}</li>`).join(''):'<li class="ls-empty">No activity yet. Collect roles or prepare an application and live progress appears here.</li>';
 return `<section class="execution-stream live-stream" aria-labelledby="execution-title"><header class="ls-head"><div class="ls-title"><i class="ls-pulse ${model.active?'on':''}" aria-hidden="true"></i><h2 id="execution-title">Execution stream</h2></div><span class="ls-meta"><span data-stream-processes>${model.processes} process${model.processes===1?'':'es'}</span> · <span data-stream-clock data-since="${model.startedAt||''}">${formatClock(model.startedAt?now-model.startedAt:0)}</span> elapsed</span></header><label class="ls-toggle"><input type="checkbox" role="switch" data-pref-review checked disabled/><span class="ls-track" aria-hidden="true"></span><span class="ls-toggle-copy"><b>Review before submit</b><small>Every application pauses here until you choose to submit.</small></span></label><div class="ls-chart">${streamSvg(model)}</div><ol class="ls-feed" aria-live="polite">${feed}</ol><footer class="ls-foot"><div><span>Today’s batch</span><strong>${model.batch.done} / ${model.batch.total}</strong></div><div class="ls-bar" role="progressbar" aria-label="Today’s batch" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><span style="width:${pct}%"></span></div></footer></section>`;
}
function refreshStream(){const region=$('[data-execution-region]');if(!region)return false;if(region.contains(document.activeElement))return true;region.innerHTML=executionStream();bindStream(region);return false}
function bindStream(region){region.querySelectorAll('[data-open-job-run]').forEach(button=>button.onclick=()=>{if(button.dataset.href==='inbox')return navigate('inbox');const task=state.tasks.find(item=>item.id===button.dataset.taskId);if(task)return openTaskDetails(task.id);if(button.dataset.openJobRun){state.processingJobId=button.dataset.openJobRun;navigate('processing');}});}
function renderHome(){
  const identity=profileIdentity(state),waiting=state.tasks.filter(task=>['needs_you','needs_setup','ready_for_review','paused','failed'].includes(task.status)&&task.type!=='collect');
  const attentionByJob=new Map();for(const task of waiting){const key=task.jobId||task.id;if(!attentionByJob.has(key))attentionByJob.set(key,task)}
  const attentionTotal=attentionByJob.size,attention=[...attentionByJob.values()].slice(0,5);
  const matches=filterJobs(state.jobs,{...defaultJobFilters,sort:'recommended'},state.tasks,state.applications).slice(0,3);
  const roles=String(state.profile.roleSearch||'').split(/[,;\n]/).map(x=>x.trim()).filter(Boolean);
  const attentionMarkup=attention.length?`<div class="attention-list">${attention.map(task=>`<article class="attention-item"><span class="attention-mark ${esc(task.status)}" aria-hidden="true">${svg(task.status==='failed'?'close':task.status==='ready_for_review'?'file':'clock')}</span><div><strong>${esc(task.company||'Application')} · ${esc(task.role||'Application')}</strong><p>${esc(displayTaskMessage(task.message||task.status.replaceAll('_',' ')))}</p><small>${esc(task.status==='ready_for_review'?'Review your tailored resume':task.status==='failed'?'A step needs attention':'Waiting for your answer or action')} · ${relativeDate(task.updatedAt||task.createdAt)}</small></div><button class="secondary-button" type="button" data-task-details="${esc(task.id)}">Open step</button></article>`).join('')}</div>`:`<div class="attention-empty"><span class="attention-mark" aria-hidden="true">${svg('check')}</span><div><strong>You’re up to date</strong><p>No application needs your attention right now.</p></div></div>`;
  return `<section class="home-welcome"><div><span class="home-welcome-kicker">${identity.name?`WELCOME BACK, ${esc(identity.name.split(/\s+/)[0]).toUpperCase()}`:'YOUR DAYMARK WORKSPACE'}</span><h1>Keep your job search moving.</h1><p>Find roles, follow application progress, and respond when a step needs you.</p></div><div class="button-row"><button class="secondary-button" data-action="import-job">Add a job link</button><button class="primary-button" data-page="jobs">Discover roles ${svg('arrow')}</button></div></section>
    ${!state.onboarding?.completed?`<div class="workspace-prompt">${svg('user')}<span>${state.setup?.ready?'Your workspace is ready to activate.':'Finish setup to activate your workspace.'}</span><button class="text-button" data-page="setup">Continue setup ${svg('arrow')}</button></div>`:''}
    <section class="content-card home-attention" aria-labelledby="attention-title"><div class="section-title-row"><div><span class="eyebrow">NEXT ACTIONS</span><h2 id="attention-title">Needs your attention <span class="attention-count">${attentionTotal}</span></h2></div><button class="text-button" data-page="applications">All applications ${svg('arrow')}</button></div>${attentionMarkup}${attentionTotal>attention.length?`<button class="text-button attention-more" data-page="applications">See all ${attentionTotal} applications needing attention ${svg('arrow')}</button>`:''}</section>
    <section class="home-stats" aria-label="Job search overview"><article><span>Roles discovered</span><strong>${state.jobs.length}</strong><small>in your workspace</small></article><article><span>In progress</span><strong>${applicationJobs().length}</strong><small>applications tracked</small></article><article><span>Submitted</span><strong>${state.applications.filter(item=>item.status==='submitted'||item.submittedAt).length}</strong><small>with recorded evidence</small></article><article><span>Collected today</span><strong>${state.dailyCollection?.newCount||0}</strong><small>of your 100 role daily limit</small></article></section>
    <div class="home-grid"><section class="home-panel" aria-labelledby="matches-title"><header class="home-panel-head"><div><span class="eyebrow">BASED ON YOUR PREFERENCES</span><h2 id="matches-title">Recommended roles</h2></div><button class="text-button" data-page="jobs">View all</button></header>${matches.length?`<div class="home-match-list">${matches.map(job=>`<article class="home-match"><span class="company-logo" data-logo-job="${esc(job.id)}" data-company="${esc(job.company)}" aria-hidden="true">${esc(initials(job.company))}</span><div class="home-match-copy"><strong>${esc(job.role)}</strong><span>${esc(job.company)} · ${esc(job.location||'Location not listed')}</span><small>${esc(job.salary||'Pay not listed')} · ${esc(job.posted||'Recently found')}</small></div><span class="home-fit">${Number(job.match)||0}% match</span><button class="secondary-button home-review" data-open-job="${esc(job.id)}">View role</button></article>`).join('')}</div>`:`<div class="home-empty"><div><strong>No recommended roles yet</strong><p>Collect fresh roles or add a public posting link to get started.</p></div><button class="secondary-button" data-page="jobs">Open Discover</button></div>`}<footer class="home-panel-foot"><span>${roles.length?`Targeting ${roles.slice(0,3).map(esc).join(', ')}`:'Set target roles in your profile to improve recommendations.'}</span><button class="text-button" data-page="profile">Edit preferences</button></footer></section><section class="home-panel home-activity-panel" aria-labelledby="activity-title"><header class="home-panel-head"><div><span class="eyebrow">RECENT WORK</span><h2 id="activity-title">Live activity</h2></div></header><div data-execution-region>${executionStream()}</div></section></div>`;
}
function filterControls(jobs){
  const f=state.jobFilters;
  const select=(key,label,items)=>`<label class="job-filter"><span>${label}</span><select data-job-filter="${key}" aria-label="${label}"><option value="">All ${label.toLowerCase()}</option>${items.map(([value,text])=>`<option value="${esc(value)}" ${f[key]===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
  const active=Object.entries(f).filter(([key,value])=>key!=='sort'&&value);
  return `<div class="job-filter-panel"><label class="job-search-control">${svg('search')}<input id="job-search" aria-label="Search jobs by role, company, or skill" placeholder="Role, company, skill…" value="${esc(f.search)}"/></label><div class="job-filter-grid"><label class="job-filter"><span>Location</span><input data-job-filter="location" aria-label="Filter by location" placeholder="Any location" value="${esc(f.location)}"/></label>${select('source','Platforms',[...new Set(jobs.map(job=>job.source).filter(Boolean))].sort().map(source=>[source,source]))}${select('age','Posting ages',[['1','Last 24 hours'],['7','Last 7 days'],['30','Last 30 days']])}${select('pay','Pay details',[['listed','Pay listed'],['missing','Pay not listed']])}${select('status','Statuses',[...applicationStatuses,['queued','Queued'],['running','Preparing'],['ready_for_review','Ready for review'],['needs_you','Needs you'],['needs_setup','Needs setup'],['paused','Paused'],['cancelled','Cancelled']])}<label class="job-filter"><span>Sort by</span><select data-job-filter="sort" aria-label="Sort jobs"><option value="recommended" ${f.sort==='recommended'?'selected':''}>Best overall · match + freshness</option><option value="newest" ${f.sort==='newest'?'selected':''}>Newest first</option><option value="match" ${f.sort==='match'?'selected':''}>Preference match</option></select></label></div>${active.length?`<div class="active-filters" aria-label="Active filters">${active.map(([key,value])=>`<button class="filter-chip" data-clear-filter="${key}" aria-label="Remove ${key} filter">${esc(key)}: ${esc(value)} ${svg('close')}</button>`).join('')}<button class="text-button" data-clear-filters>Clear filters</button></div>`:''}</div>`;
}
function importRoleCard(){return `<article class="job-card import-role-card"><span class="eyebrow">HAVE A ROLE IN MIND?</span><h3>Add a job link.</h3><p>Paste a public posting link. Daymark reads its details and adds it to your roles.</p><form id="import-role-form"><label for="import-role-url">Job posting link</label><input id="import-role-url" name="url" type="url" required placeholder="https://company.com/careers/role" value="${esc(state.importLinkDraft)}"/><button class="primary-button" type="submit" ${state.importing?'disabled':''}>${state.importing?'Fetching…':'Fetch job'} ${svg('arrow')}</button><p id="import-role-status" role="status">${state.importing?'Fetching posting details…':''}</p></form></article>`;}
function cardsResult(jobs,{application=false}={}){
 const bucketFilter=application&&['in_flight','needs_you','failed','submitted','skipped'].includes(state.jobFilters.status);
 const filtered=filterJobs(jobs,bucketFilter?{...state.jobFilters,status:''}:state.jobFilters,state.tasks,state.applications).filter(job=>!bucketFilter||applicationBucket(state,job)===state.jobFilters.status),page=paginateJobs(filtered,state.jobPage);state.jobPage=page.page;
 const pageNumbers=Array.from(new Set([1,page.pages,...Array.from({length:5},(_,i)=>page.page+i-2).filter(n=>n>0&&n<=page.pages)])).sort((a,b)=>a-b);
 return `<div class="results-heading" role="status">${page.total?`${page.start}–${page.end} of ${page.total}`:'0'} ${application?'applications':'roles'}</div>${!application&&state.importedJob?`<section class="imported-role-result"><div class="section-title-row"><h2>Imported role</h2><button class="text-button" data-dismiss-import>Close preview</button></div><div class="job-card-grid">${jobCard(state.importedJob)}</div></section>`:''}<div class="${application?'ws-ledger':'job-card-grid'}">${application?applicationLedger(page.items):importRoleCard()+page.items.map(job=>jobCard(job,{application})).join('')}</div>${!page.items.length?`<div class="content-card empty-state"><strong>${jobs.length?'No roles match these filters.':application?'No applications underway yet.':'Your job collection starts here.'}</strong><p>${jobs.length?'Broaden your search or clear the filters.':application?'Choose a role from Discover.':'Import a posting link above or collect fresh jobs.'}</p>${jobs.length?'<button class="secondary-button" data-clear-filters>Clear filters</button>':application?'<button class="secondary-button" data-page="jobs">Discover jobs</button>':''}</div>`:''}${page.pages>1?`<nav class="job-pagination" aria-label="Role pages"><button class="secondary-button" data-job-page="${page.page-1}" ${page.page===1?'disabled':''}>Previous</button><div>${pageNumbers.map((n,i)=>`${i&&n-pageNumbers[i-1]>1?'<span aria-hidden="true">…</span>':''}<button class="page-number" data-job-page="${n}" ${n===page.page?'aria-current="page"':''} aria-label="Page ${n}">${n}</button>`).join('')}</div><button class="secondary-button" data-job-page="${page.page+1}" ${page.page===page.pages?'disabled':''}>Next</button><span>Page ${page.page} of ${page.pages}</span></nav>`:''}`;
}
function renderJobs(){return `${heading('DISCOVER','Find your next opportunity.','Fresh roles, clear details, and materials tailored to your next move.','<div class="button-row"><button class="secondary-button" data-action="import-job">Import posting</button><button class="primary-button" data-action="collect">'+svg('refresh')+' Collect jobs</button></div>')}${filterControls(state.jobs)}<div data-job-results>${cardsResult(state.jobs)}</div>`}
function applicationJobs(){
  const ids=new Set([...state.tasks.filter(task=>task.type!=='collect').map(task=>task.jobId),...state.applications.map(item=>item.jobId)].filter(Boolean));
  const jobs=state.jobs.filter(job=>ids.has(job.id));
  for(const app of state.applications)if(!jobs.some(job=>job.id===app.jobId||job.id===app.id))jobs.push({...app,id:app.id,source:app.ats||app.source,first_seen_at:app.updatedAt,historical:true});
  for(const task of state.tasks)if(task.type!=='collect'&&!jobs.some(job=>job.id===task.jobId))jobs.push({id:task.jobId||task.id,company:task.company,role:task.role,source:task.destination,first_seen_at:task.createdAt});
  return jobs;
}
function applicationLedger(jobs){return `<div class="ws-ledger-head"><span>Company & role</span><span>Status</span><span>Last update</span><span></span></div>${jobs.map(job=>{const m=workspaceModel(state,job.id),bucket=applicationBucket(state,job),label=m.recorded?'Recorded as submitted':({submitted:'Submitted',needs_you:'Needs you',failed:'Issue',skipped:'Skipped',in_flight:'In progress'})[bucket]||bucket.replaceAll('_',' ');return `<article class="ws-ledger-row"><div class="ws-company-mark" aria-hidden="true">${esc(initials(job.company))}</div><div><h3><button data-application-status="${esc(job.id)}">${esc(job.role||'Application')}</button></h3><p>${esc(job.company)}</p></div><span class="ws-ledger-state ${esc(bucket)}">${esc(label)}</span><time>${esc(relativeDate(m.current?.updatedAt||m.record?.updatedAt||job.first_seen_at))}</time><button class="ws-row-open" data-application-status="${esc(job.id)}" aria-label="Open ${esc(job.company)} application">↗</button></article>`}).join('')}`;}
function applicationTabs(){const jobs=applicationJobs(),tabs=[['','All'],['needs_you','Review'],['in_flight','In progress'],['submitted','Sent'],['failed','Issues'],['skipped','Skipped']];return `<div class="app-tabs ws-list-tabs" role="tablist" aria-label="Application status">${tabs.map(([value,label])=>`<button type="button" role="tab" class="app-tab" data-app-tab="${value}" aria-selected="${(state.jobFilters.status||'')===value}"><span>${value?jobs.filter(j=>applicationBucket(state,j)===value).length:jobs.length}</span>${label}</button>`).join('')}</div>`;}
function applicationViewTabs(){return `<nav class="tracker-tabs" aria-label="Application views"><button type="button" data-page="applications" aria-current="${state.page==='applications'?'page':'false'}">Application list</button><button type="button" data-page="pipeline" aria-current="${state.page==='pipeline'?'page':'false'}">Pipeline</button></nav>`}
function renderApplications(){
 const jobs=applicationJobs();
 return heading('APPLICATIONS','Applications','Review, approve, and track every application.',`<div class="button-row"><button class="secondary-button" data-submit-all>Review ready items</button><button class="primary-button" data-page="jobs">Discover roles ${svg('arrow')}</button></div>`)+applicationViewTabs()+applicationTabs()+filterControls(jobs)+`<div data-job-results>${cardsResult(jobs,{application:true})}</div>`;
}
function renderPipeline(){
 const jobs=applicationJobs();
 const lanes=[['in_flight','In flight','Preparation and form filling'],['needs_you','Needs you','Questions and recovery'],['submitted','Submitted','Confirmed applications'],['interview','Interviewing','Screening, interviews, and offers'],['closed','Closed','Failed, skipped, rejected, or withdrawn']];
 const laneFor=job=>{const status=jobStatus(job,state.tasks,state.applications);if(['needs_you','needs_setup','paused'].includes(status))return'needs_you';if(['submitted'].includes(status))return'submitted';if(['screening','interview','offer'].includes(status))return'interview';if(['failed','skipped','rejected','withdrawn','cancelled'].includes(status))return'closed';return'in_flight'};
 return heading('APPLICATIONS','Follow the whole pipeline.','Group roles by their recorded status and open any application to see its next step.',`<button class="primary-button" data-page="jobs">Discover roles ${svg('arrow')}</button>`)+applicationViewTabs()+`<div class="pipeline-board">${lanes.map(([key,title,description])=>{const items=jobs.filter(job=>laneFor(job)===key);return `<section class="pipeline-lane" aria-label="${title}: ${items.length} applications"><header><div><h2>${title}</h2><p>${description}</p></div><span>${items.length}</span></header><div class="pipeline-items">${items.length?items.map(job=>jobCard(job,{application:true})).join(''):`<p class="pipeline-empty">No applications here yet.</p>`}</div></section>`}).join('')}</div>`;
}
function renderAutoApply(){
 const prefs=state.preferences||{},automation=prefs.autoApply||{},cap=Math.max(0,Number(automation.dailyCap??10)),used=Number(state.dailyAutoApply?.count||0);
 return heading('AUTO APPLY / LOCAL CONTROLS','Set your rules. Keep control.','Tune matching, daily limits, and skip rules for the local application worker.')+`<section class="auto-apply-status content-card"><span class="worker-health ${automation.enabled!==false?'ready':''}"><i></i>${automation.enabled!==false?'Automation enabled':'Automation paused'}</span><div class="auto-apply-metrics"><div><span>Shared daily cap</span><strong>${cap} / day</strong></div><div><span>Used today</span><strong>${used} / ${cap}</strong></div><div><span>Applications in queue</span><strong>${applicationJobs().length}</strong></div></div><p>Collection and applications run on this Mac. Apify collection may incur provider charges; only your configured daily cap is queued.</p></section>${automationCard()}<section class="content-card"><h2>Submission review</h2><label class="ls-toggle"><input type="checkbox" role="switch" data-pref-review checked disabled/><span class="ls-track" aria-hidden="true"></span><span class="ls-toggle-copy"><b>Stop for your review before submission</b><small>Required for every application. Daymark will not submit automatically.</small></span></label><div class="inline-note">Your first live workflow test will stop here so you can inspect the employer form and tailored resume.</div></section>`;
}
function manualApplicationClosed(){const app=state.applications.find(item=>item.jobId===state.processingJobId||item.id===state.processingJobId);return Boolean(app?.manuallyUpdated&&!['in_progress','filled'].includes(app.status));}
function manualStatusControl(){const app=state.applications.find(item=>item.jobId===state.processingJobId||item.id===state.processingJobId);return `<section class="content-card manual-status-card"><h2>Application status</h2><p>Update this after completing steps yourself. This records your progress locally.</p><form id="manual-status-form"><label for="manual-application-status">Current status</label><select id="manual-application-status" name="status" required><option value="" disabled ${!app?'selected':''}>Choose status</option>${applicationStatuses.map(([id,label])=>`<option value="${id}" ${app?.status===id?'selected':''}>${label}</option>`).join('')}</select><button class="secondary-button" type="submit">Save status</button><p id="manual-status-message" role="status">${app?.manuallyUpdated?`Updated by you · ${relativeDate(app.updatedAt)}`:''}</p></form></section>`;}

function humanReviewPanel(task){
 const kind=task?.reviewState?.required?task.reviewState.kind:'';if(!kind)return '';
 const labels={answers_needed:'Answers needed',verification_required:'Employer verification needed',authentication_required:'Sign in to continue',legal_review_required:'Review the employer agreement',control_review_required:'Check this application control',flow_intervention:'Application flow needs a check',submission_confirmation_required:'Confirm the submission result',final_review_required:'Review before submission',user_action_required:'Your input is needed'};
 const guidance={answers_needed:'Daymark paused because a required answer is not confirmed. Review the questions above and continue when they are complete.',verification_required:'Daymark saved the current step and is waiting for you to verify or resolve it.',authentication_required:'Complete sign-in in the saved application session, then return here to continue.',legal_review_required:'Read the employer statement and choose whether to accept it before continuing.',control_review_required:'This page contains a control Daymark cannot safely operate. Resolve it in the saved session.',flow_intervention:'The employer returned to a previous step or exceeded the safe step limit. Check the live form before continuing.',submission_confirmation_required:'Daymark will not repeat an uncertain submission. Check the employer page or inbox first.',final_review_required:'Review the tailored resume and application answers before submission.',user_action_required:'Resolve the saved checkpoint before Daymark continues.'};
 const verified=(task.verifiedFields||[]).filter(field=>['verified','rejected'].includes(field.status)).slice(-24).reverse();
 return `<div class="inline-note human-review-state"><strong>${esc(labels[kind]||labels.user_action_required)}</strong><p>${esc(guidance[kind]||guidance.user_action_required)}</p>${verified.length?`<details><summary>Field checks · ${verified.length}</summary><ul>${verified.map(field=>`<li>${esc(field.label)} · ${field.status==='verified'?'Verified':'Needs attention'}${field.reason?` — ${esc(field.reason)}`:''}</li>`).join('')}</ul></details>`:''}</div>`;
}
function applicationPresentation(){
 const model=applicationPresentationModel(state.tasks,state.processingJobId),job=state.jobs.find(item=>item.id===state.processingJobId),task=applicationRun(state.tasks,state.processingJobId).current;
 const active=['queued','running'].includes(task?.status),events=model.events.length?model.events.slice(0,5).map(item=>`<li class="agent-event"><span class="agent-event-dot ${esc(item.status||'')}" aria-hidden="true">${svg(item.status==='failed'?'close':item.status==='running'?'clock':'check')}</span><div><strong>${esc(displayTaskMessage(item.message||item.status))}</strong><small>${esc(item.type==='prepare'?'Preparing documents':'Application form')} · ${relativeDate(item.at)}</small></div></li>`).join(''):'<li class="agent-empty">Activity will appear here when this application begins.</li>';
 const stages=model.stages.map(stage=>`<li class="agent-stage ${esc(stage.status)}"><span class="agent-stage-icon" aria-hidden="true">${svg(stage.status==='complete'?'check':stage.status==='failed'?'close':stage.status==='waiting'?'file':'clock')}</span><div><strong>${esc(stage.label)}</strong><small>${esc(stage.detail)}</small></div><span class="agent-stage-state">${esc(({complete:'Done',active:'In progress',waiting:'Waiting for you',failed:'Needs attention',idle:'Up next'})[stage.status])}</span></li>`).join('');
 return `<section class="execution-stream application-presentation" aria-labelledby="application-agent-title" aria-live="polite"><header class="stream-header"><div><p class="eyebrow">DAYMARK · BACKGROUND AGENT</p><h2 id="application-agent-title">${esc(model.current.title)}</h2><p>${esc(job?.company||'This employer')} · ${esc(job?.role||'Application')}</p></div><span class="stream-live ${active?'active':''}"><i aria-hidden="true"></i>${active?'Working':model.submitted?'Submitted':task?.status==='needs_you'?'Paused for review':'Saved'}</span></header><div class="agent-current"><span class="agent-orbit ${active?'active':''}" aria-hidden="true">${svg(model.submitted?'check':task?.status==='failed'?'alert':'clock')}</span><div><span class="eyebrow">CURRENT UPDATE</span><p>${esc(model.current.message)}</p><small>${model.current.at?`Updated ${relativeDate(model.current.at)}`:'No processing activity yet'}</small></div></div><ol class="agent-pathway" aria-label="Application steps">${stages}</ol><div class="agent-log"><h3>Live activity</h3><ol>${events}</ol></div><p class="agent-privacy-note">The employer form stays in its background session. This screen shows the worker’s recorded progress and pauses for your review when needed.</p></section>`;
}
async function saveManualStatus(event){
 event.preventDefault();const form=event.target.closest('#manual-status-form');if(!form||form.dataset.saving==='true')return;
 const status=new FormData(form).get('status'),button=form.querySelector('button'),message=form.querySelector('[role="status"]');
 if(!status){message.textContent='Choose an application status first.';return;}
 form.dataset.saving='true';button.disabled=true;message.textContent='Saving status…';
 try{const result=await api(`/api/applications/${encodeURIComponent(state.processingJobId)}/status`,{method:'POST',body:JSON.stringify({status})});state.applications=[result.application,...state.applications.filter(item=>item.id!==result.application.id)];state.tasks=result.tasks;render();toast('Application status saved.');}
 catch(error){if(form.isConnected)message.textContent=error.message;toast(error.message,true);}
 finally{if(form.isConnected){delete form.dataset.saving;button.disabled=false;}}
}
// Delegate so polling and document-panel replacements cannot detach status saving.
document.addEventListener('submit',event=>{if(event.target.matches('#manual-status-form'))void saveManualStatus(event);});
let workspacePane='form';let workspaceJob='';let workspaceRevision='';
function wsModel(){const run=applicationRun(state.tasks,state.processingJobId),revision=[state.processingJobId,run.current?.updatedAt,run.prepare?.review?.approvedAt].join(':');if(workspaceRevision!==revision){workspaceRevision=revision;state.workspaceDraftDirty=false;}const m=workspaceModel(state,state.processingJobId);if(state.workspaceDraftDirty&&!m.closed)m.message='Save your answer or resume changes before submitting. Daymark will recheck the employer form.';return m;}
function processingLive(){
 const m=wsModel(),run=applicationRun(state.tasks,state.processingJobId);
 if(m.closed)return workspaceReceipt(m,{esc,svg});
 const editable=run.fill?.checkpoint?.questions?.filter(q=>!q.manual&&!['password','file'].includes(q.type)&&!/first name|last name|email|phone|resume|cover letter/i.test(q.label))||[];
 const finalEditor=run.fill?.finalReviewReady&&editable.length?questionPanel({...run.fill,checkpoint:{...run.fill.checkpoint,unresolvedIds:editable.map(q=>q.id)}}).replace('Answers needed','Review application answers').replace('Apply answers and continue','Save changes & recheck'):'';
 const blocker=finalEditor||(run.fill?.reviewState?.kind==='answers_needed'?questionPanel(run.fill):'');
 const resolution=run.fill&&!run.fill.finalReviewReady&&!m.uncertain?resolutionPanel(run.fill,run.fill.recoveryUrl||m.job.url,state.worker):'';
 const editableLabels=new Set(editable.map(q=>q.label.replace(/\*+$/,'').trim().toLowerCase()));
 const receiptModel=finalEditor?{...m,fill:{...m.fill,filledSteps:(m.fill.filledSteps||[]).map(step=>({...step,answers:step.answers.filter(a=>!editableLabels.has(a.label.replace(/\*+$/,'').trim().toLowerCase()))})).filter(step=>step.answers.length)}}:m;
 return `${finalEditor?workspaceReceipt(receiptModel,{esc,svg})+finalEditor:blocker+resolution+workspaceReceipt(m,{esc,svg})}${m.uncertain?`<section class="ws-form-section"><h3>Check before retrying</h3><p>Daymark will not send another application until you confirm the employer did not receive this one.</p><button class="secondary-button" data-page="inbox">Check inbox</button><button class="text-button" data-clear-submit="${esc(run.fill.id)}">Nothing received · allow retry</button></section>`:''}`;
}
function workspaceDiagnostics(m){const d=m.current?.diagnostics;if(!d)return '<p class="ws-empty">The next worker run will record a task trace here.</p>';const seconds=ms=>`${Math.round((ms||0)/1000)}s`;return `<details class="ws-diagnostics"><summary>Worker trace · ${esc(d.owner)} · ${esc(d.state.replaceAll('_',' '))}</summary><dl><div><dt>Task</dt><dd>${esc(d.taskId)}</dd></div><div><dt>${d.timingKind==='waiting'?'Time waiting at this checkpoint':'Time in this phase'}</dt><dd>${seconds(d.phaseAgeMs)}</dd></div><div><dt>Blocker</dt><dd>${esc(d.blockedBy||'None')}</dd></div><div><dt>Retry</dt><dd>${d.retryAllowed?'Available before submission':'Requires review'}</dd></div></dl><ol>${d.timeline.map(t=>`<li><span>${esc(t.state.replaceAll('_',' '))}</span><time>${seconds(t.durationMs)}</time></li>`).join('')}</ol><p>Durations cover retained transitions. No credentials or answer content are included.</p></details>`;}
function renderProcessing(){
 const m=wsModel(),run=applicationRun(state.tasks,state.processingJobId);if(workspaceJob!==state.processingJobId){workspaceJob=state.processingJobId;workspacePane='form';}
 const tabs=[['form','file','Form'],['resume','file','Resume'],['cover','mail','Cover'],['job','layers','Job']];
 const pane=workspacePane==='form'?`<div data-processing-live>${processingLive()}</div>${workspaceDiagnostics(m)}<details class="ws-record-status"><summary>Record an employer outcome</summary>${manualStatusControl()}</details>`:workspacePane==='resume'?`<section class="processing-documents" data-processing-documents data-editor-key="${run.approved?'approved':'draft'}"><div data-inline-review>${processingDocuments()}</div></section>`:workspacePane==='cover'?`<div class="ws-pane-heading"><h2>Cover letter</h2></div>${run.prepare?.review?.coverLetter?`<article class="ws-letter">${esc(run.prepare.review.coverLetter)}</article>`:'<div class="ws-empty">'+svg('mail')+'<h3>No cover letter prepared</h3><p>The source-only pilot prepares your resume. It does not generate or attach a cover letter.</p></div>'}`:`<div class="ws-pane-heading"><h2>Job description</h2>${m.job.url?`<a href="${esc(m.job.url)}" target="_blank" rel="noreferrer">View posting ↗</a>`:''}</div><article class="ws-job-copy">${esc(m.job.description||'No job description was saved for this application.')}</article>`;
 return `<!-- THESIS: One application, one current action. OWN-WORLD: Tsenta reference; ivory canvas, white dossier, forest controls. STORY: Inspect account access, review answers, approve sending, verify receipt. FIRST VIEWPORT: Employer header, compact phase, next action, four document tabs. FORM: User-pinned competitor layout; no concept roll. --><div class="application-workspace"><button class="ws-back" data-page="applications">← Applications</button><header class="ws-employer"><div><h1>${esc(m.job.company||m.current?.company||'Application')}</h1><p>${esc(m.job.role||m.current?.role||'Application workspace')}</p></div>${m.job.url?`<a href="${esc(m.job.url)}" target="_blank" rel="noreferrer">View job posting ↗</a>`:''}</header><div data-workspace-status>${workspaceStatus(m,{esc,svg,relativeDate})}</div><section class="ws-dossier"><nav class="ws-tabs" role="tablist" aria-label="Application documents">${tabs.map(([id,icon,label])=>`<button id="ws-tab-${id}" role="tab" aria-selected="${workspacePane===id}" aria-controls="ws-panel" data-workspace-pane="${id}" tabindex="${workspacePane===id?0:-1}">${svg(icon)}<span>${label}</span></button>`).join('')}</nav><div id="ws-panel" role="tabpanel" aria-labelledby="ws-tab-${workspacePane}">${pane}</div></section>${!m.closed?`<footer class="ws-footer"><span>Saved locally · Sign-in and final approval required</span><button class="text-button" data-skip-application="${esc(state.processingJobId)}">Skip application</button></footer>`:''}</div>`;
}
function canSubmitNow(run){return Boolean(run.fill?.authStatus==='authenticated'&&run.approved&&run.fill?.finalReviewReady&&!run.fill.submitAttemptedAt&&run.fill.status==='needs_you');}
function processingDocuments(){
 const run=applicationRun(state.tasks,state.processingJobId),task=run.prepare;
 if(!task?.review)return '<div class="ws-empty"><h3>Preparing your resume</h3><p>Your tailored document will appear here when preparation finishes.</p></div>';
 return `<div class="ws-resume-toolbar"><div><h2>${run.approved?'Approved resume':'Tailored resume'}</h2><small>${run.approved?'Reviewed for this application':'Prepared from your verified experience'}</small></div><div class="ws-resume-actions"><label class="ws-template-label">Template <select data-resume-template="${esc(task.id)}" aria-label="Resume template"><option value="standard" ${task.review.format?.template!=='jake'?'selected':''}>Standard</option><option value="jake" ${task.review.format?.template==='jake'?'selected':''}>Jake</option></select></label>${run.approved?`<a href="/api/tasks/${esc(task.id)}/files/resume.pdf" download>↓ Download PDF</a>`:''}${!manualApplicationClosed()?`<button class="text-button" data-edit-final="${esc(task.id)}">${run.approved?'Edit resume':'Review & approve'}</button>`:''}</div></div><div class="ws-document-canvas"><iframe class="resume-preview-frame" data-processing-preview title="${run.approved?'Approved':'Tailored'} application resume"></iframe></div>`;
}
function bindProcessingDocuments(){
 if(state.page!=='processing'||workspacePane!=='resume')return;
 const region=$('[data-inline-review]');if(!region)return;
 const run=applicationRun(state.tasks,state.processingJobId),preview=$('[data-processing-preview]');
 if(preview&&run.prepare?.review)preview.src=`/api/tasks/${encodeURIComponent(run.prepare.id)}/preview/resume.pdf#toolbar=0&navpanes=0&view=FitH`;
 const edit=$('[data-edit-final]');if(edit)edit.onclick=()=>{openResumeReview(run.prepare.id,region);$('#resume-review-form').onsubmit=approveResumeReview;};
}
function updateProcessing(){
 if(state.page!=='processing')return false;
 const root=$('.application-workspace');if(!root)return false;
 const active=document.activeElement,status=$('[data-workspace-status]'),m=wsModel();
 if(status&&!status.contains(active)){const open=status.querySelector('.ws-activity')?.open;status.innerHTML=workspaceStatus(m,{esc,svg,relativeDate});if(open)status.querySelector('.ws-activity').open=true;bindTaskDetailsActions(status);}
 const editorBusy=root.contains(active)&&active.matches('input,textarea,select');
 if(m.closed)root.querySelector('.ws-footer')?.remove();
 if(editorBusy)return true;
 const form=$('[data-processing-live]');if(form&&!form.contains(active)&&!form.querySelector('details[open]')){form.innerHTML=processingLive();bindTaskDetailsActions(form);}
 const trace=root.querySelector('.ws-diagnostics');if(trace&&!trace.open){const holder=document.createElement('div');holder.innerHTML=workspaceDiagnostics(m);trace.replaceWith(holder.firstElementChild);}
 const docs=$('[data-processing-documents]'),key=m.closed?'recorded':m.approved&&m.finalReady?'approved':m.finalReady?'final':m.prepare?.hasArtifacts?'preview':'waiting';
 if(docs&&docs.dataset.editorKey!==key){docs.dataset.editorKey=key;$('[data-inline-review]').innerHTML=processingDocuments();bindProcessingDocuments();}
 return false;
}
document.addEventListener('click',async event=>{const pane=event.target.closest?.('[data-workspace-pane]');if(pane){workspacePane=pane.dataset.workspacePane;render();$(`[data-workspace-pane="${workspacePane}"]`)?.focus();return;}const skip=event.target.closest?.('[data-skip-application]');if(skip){skip.disabled=true;try{await api(`/api/applications/${encodeURIComponent(skip.dataset.skipApplication)}/status`,{method:'POST',body:JSON.stringify({status:'skipped'})});await loadState();toast('Application skipped.');}catch(error){toast(error.message,true);skip.disabled=false;}}});
document.addEventListener('input',event=>{if(state.page==='processing'&&event.target.matches('[data-question],#review-resume-text')){state.workspaceDraftDirty=true;updateProcessing();}});
document.addEventListener('keydown',event=>{const tab=event.target.closest?.('.ws-tabs [role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const items=[...tab.parentElement.querySelectorAll('[role="tab"]')],i=items.indexOf(tab);items[event.key==='Home'?0:event.key==='End'?items.length-1:(i+(event.key==='ArrowRight'?1:-1)+items.length)%items.length].click();});
document.addEventListener('focusout',event=>{if(event.target.closest?.('[data-processing-documents]')&&state.processingRefreshPending)state.processingRefreshPending=updateProcessing();});
function renderSetup(){
 const step=state.onboarding?.step||'connections';
 const progress=`<nav class="setup-progress" aria-label="Setup progress">${setupSteps.map((key,i)=>`<button type="button" data-setup-step="${key}" ${key===step?'aria-current="step"':''}><span>${i+1}</span>${({connections:'Connections',resume:'Resume',profile:'Review profile',answers:'Answer pack',ready:'Ready'})[key]}</button>`).join('')}</nav>`;
 if(step==='ready')return progress+heading('ACTIVATE YOUR WORKSPACE',state.setup?.ready?'Ready for your next move.':'Complete your workspace.','Your progress is saved locally. Review the checklist before activating.')+setupChecklist();
 return progress+(step==='connections'?renderSettings()+`<div class="setup-footer"><p>Save your keys, Bridge access, and default ATS password.</p><button class="primary-button" data-setup-step="resume">Continue to resume ${svg('arrow')}</button></div>`:step==='answers'?renderAnswers():renderProfile());
}
function openTaskDetails(id){const task=state.tasks.find(item=>item.id===id);if(!task)return;state.processingJobId=task.jobId;navigate('processing');$('#application-questions h2')?.focus({preventScroll:false});}
function openHistoricalJob(id){
 const app=state.applications.find(item=>item.id===id);if(!app)return;state.processingJobId=app.jobId||app.id;navigate('processing');return;
 const dialog=$('#job-dialog');dialog.innerHTML=`<div class="dialog-head"><div><h2>${esc(app.role||'Application')}</h2><p>${esc(app.company||'Company not recorded')}</p></div>${iconButton('close','Close dialog','data-close-dialog')}</div><div class="dialog-body"><p>Recorded status: ${esc(app.status||'Not recorded')}</p><p>Platform: ${esc(app.ats||app.source||'Not recorded')}</p><p>Updated: ${esc(app.updatedAt||'Date not recorded')}</p></div>`;if(!dialog.open)dialog.showModal();dialog.querySelector('[data-close-dialog]').onclick=()=>dialog.close();
}
function refreshJobResults(){
 const panel=$('.job-filter-panel');if(panel){let chips=panel.querySelector('.active-filters');if(!chips){chips=document.createElement('div');chips.className='active-filters';panel.append(chips);}chips.innerHTML=Object.entries(state.jobFilters).filter(([key,value])=>key!=='sort'&&value).map(([key,value])=>`<button class="filter-chip" data-clear-filter="${key}">${esc(key)}: ${esc(value)} ${svg('close')}</button>`).join('');chips.querySelectorAll('[data-clear-filter]').forEach(button=>button.onclick=()=>{state.jobFilters[button.dataset.clearFilter]='';state.jobPage=1;render()});}

 const region=$('[data-job-results]');if(!region)return;
 region.innerHTML=cardsResult(state.page==='applications'?applicationJobs():state.jobs,{application:state.page==='applications'});bindCardActions(region);
}
function bindCardActions(root=document){
 root.querySelectorAll('[data-card-job]').forEach(card=>card.onclick=event=>{if(!event.target.closest('button,a,input')){if(card.dataset.cardHistory==='true')openHistoricalJob(card.dataset.cardJob);else openJob(card.dataset.cardJob);}});
 root.querySelectorAll('[data-apply-job]').forEach(button=>button.onclick=()=>createTask(button.dataset.applyJob));

 root.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));

 root.querySelectorAll('[data-open-job]').forEach(button=>button.onclick=()=>openJob(button.dataset.openJob));
 root.querySelectorAll('[data-application-status]').forEach(button=>button.onclick=()=>{state.processingJobId=button.dataset.applicationStatus;navigate('processing');});
 root.querySelectorAll('[data-task-details]').forEach(button=>button.onclick=()=>openTaskDetails(button.dataset.taskDetails));
 root.querySelectorAll('[data-history-job]').forEach(button=>button.onclick=()=>openHistoricalJob(button.dataset.historyJob));
 bindCompanyLogos(root);
 root.querySelectorAll('[data-job-page]').forEach(button=>button.onclick=()=>{state.jobPage=Number(button.dataset.jobPage);refreshJobResults();$('[data-job-results]')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});$('[data-job-page][aria-current]')?.focus({preventScroll:true});});
 const importForm=root.querySelector('#import-role-form');if(importForm){importForm.onsubmit=importRole;importForm.elements.url.oninput=()=>state.importLinkDraft=importForm.elements.url.value;}
 root.querySelector('[data-dismiss-import]')?.addEventListener('click',()=>{state.importedJob=null;refreshJobResults();});
 root.querySelectorAll('[data-clear-filters]').forEach(button=>button.onclick=()=>{state.jobFilters={...defaultJobFilters};state.jobPage=1;render()});
}

function bindTaskDetailsActions(root){
 root.querySelectorAll('[data-task-action]').forEach(button=>button.onclick=()=>taskAction(button.dataset.id,button.dataset.taskAction));
 root.querySelectorAll('[data-review-task]').forEach(button=>button.onclick=()=>openResumeReview(button.dataset.reviewTask));
 root.querySelectorAll('[data-job-answer]').forEach(button=>button.onclick=()=>draftJobAnswer(button.dataset.jobAnswer));
 root.querySelectorAll('[data-fill-task]').forEach(button=>button.onclick=()=>fillTask(button.dataset.fillTask));
}

updateQuestionsBar=bindQuestionsInbox({getState:()=>state,api:(url,body)=>api(url,{method:'POST',body:JSON.stringify(body)}),notify:toast,openApplication:jobId=>{state.processingJobId=jobId;navigate('processing')},afterSend:async({refresh,rerender}={})=>{if(refresh){const data=await api('/api/state');state.tasks=data.tasks;state.applications=data.applications;}render();}});
bindQuestionEvents({api:(url,body)=>api(url,{method:'POST',body:JSON.stringify(body)}),refresh:async()=>{const data=await api('/api/state');state.tasks=data.tasks;state.applications=data.applications;updateProcessing();updateCardActivities();},taskFor:id=>state.tasks.find(task=>task.id===id),notify:toast});

document.addEventListener('change',async event=>{const control=event.target.closest?.('[data-resume-template]');if(!control)return;control.disabled=true;try{const result=await api(`/api/tasks/${control.dataset.resumeTemplate}/resume-format`,{method:'POST',body:JSON.stringify({template:control.value})});state.tasks=state.tasks.map(t=>t.id===result.task.id?result.task:t);await loadState();render();toast('Resume format updated. Review the new attachment before submitting.');}catch(error){toast(error.message,true);control.disabled=false;}});
